def _parse_int_arg(opt_display, val):
    # opt_display e.g. '-j' or '--error-exitcode='
    # integer parsing: allow negative? std::stoi like: leading spaces? digits with optional sign, trailing garbage invalid?
    # Observed abc -> not integer, =2 for -j -> "=2" not integer.
    s=val.strip()
    if not re.fullmatch(r'[+-]?\d+', s or ''):
        raise CliError(f"cppcheck: error: argument to '{opt_display}' is not valid - not an integer.\n")
    return int(s)

def _enable_expand(name):
    if name=='style': return {'style','warning','performance','portability'}
    if name=='all': return {'style','warning','performance','portability','information','unusedFunction','missingInclude'}
    return {name}

def _apply_enable(settings, value, kind):
    # kind enable/disable
    if value=="":
        raise CliError(f"cppcheck: error: --{kind} parameter is empty\n")
    parts=value.split(',')
    for p in parts:
        if p=="":
            raise CliError(f"cppcheck: error: --{kind}--enable parameter is empty\n")
        if p not in VALID_ENABLE:
            raise CliError(f"cppcheck: error: --{kind} parameter with the unknown name '{p}'\n")
        if kind=='enable':
            settings.enabled.update(_enable_expand(p))
        else:
            # disable: remove semantics stored in disabled set
            if p=='all':
                settings.disabled.update({'style','warning','performance','portability','information','unusedFunction','missingInclude'})
            else:
                settings.disabled.add(p)

def _load_suppressions_list(settings, fname, is_exitcode=False):
    try:
        with open(fname,'r',encoding='latin-1') as f:
            lines=f.read().splitlines()
    except Exception:
        raise CliError(f'cppcheck: error: couldn\'t open the file: "{fname}".\n')
    target = settings.exitcode_suppressions if is_exitcode else settings.suppressions
    for line in lines:
        if line=="" :
            continue
        if line.startswith('#') or line.startswith('//'):
            continue
        stripped=line
        # trailing comments? "id // trailing" - cppcheck strips ??? observed it worked: cut at " //"?
        # But a line like "invalid ... with spaces" should raise invalid id with whole line. So only strip if second token starts with // or #?
        # implementation: if ' //' in line, cut before it; if ' #' - maybe not.
        if ' //' in stripped:
            stripped=stripped.split(' //',1)[0]
        if stripped=="" :
            continue
        sup=parse_suppression_spec(stripped)
        target.append(sup)

def _load_suppressions_xml(settings, fname):
    # tinyxml error codes naming
    if not os.path.isfile(fname):
        raise CliError(f"cppcheck: error: failed to load suppressions XML '{fname}' (XML_ERROR_FILE_NOT_FOUND).\n")
    try:
        tree=ET.parse(fname)
    except ET.ParseError as e:
        # differentiate empty / parsing text?
        try:
            content=open(fname,'rb').read()
        except:
            content=b''
        if len(content.strip())==0:
            code="XML_ERROR_EMPTY_DOCUMENT"
        else:
            code="XML_ERROR_PARSING_TEXT"
        raise CliError(f"cppcheck: error: failed to load suppressions XML '{fname}' ({code}).\n")
    root=tree.getroot()
    for sup_el in root.iter('suppress'):
        id_=''; fname2=''; line=None; symbol=None
        for child in sup_el:
            txt=(child.text or '')
            if child.tag=='id': id_=txt
            elif child.tag in ('fileName','file'): fname2=txt
            elif child.tag in ('lineNumber','line'):
                try: line=int(txt)
                except: line=None
            elif child.tag=='symbolName': symbol=txt
        if not id_:
            raise CliError("cppcheck: error: Failed to add suppression. No id.\n")
        if re.search(r'[^A-Za-z0-9_\*\?]', id_):
            raise CliError(f'cppcheck: error: Failed to add suppression. Invalid id "{id_}"\n')
        settings.suppressions.append(Suppression(id_,fname2,line,symbol))

def _load_file_list(settings, fname, stdin_data_holder):
    if fname=='-':
        data=sys.stdin.buffer.read().decode('latin-1')
        lines=data.splitlines()
    else:
        try:
            lines=open(fname,encoding='latin-1').read().splitlines()
        except Exception:
            raise CliError(f'cppcheck: error: couldn\'t open the file: "{fname}".\n')
    for line in lines:
        line=line.strip()
        if not line: continue
        # comment lines? observed # comment in list was ignored because file not found maybe; keep as path if starts with #? It resulted in 2 files, so either ignored as nonexistent path. We'll add as path and later nonexistent paths are ignored if some exist. That matches behaviour.
        settings.paths.append(line)

def _load_project(settings, fname):
    if not os.path.isfile(fname):
        # failed to open project 'x'. The file does not exist.
        raise CliError(f"cppcheck: error: failed to open project '{fname}'. The file does not exist.\n")
    # determine type by extension/content
    lower=fname.lower()
    try:
        data=open(fname,'rb').read().decode('latin-1')
    except Exception:
        raise CliError(f"cppcheck: error: failed to open project '{fname}'. The file does not exist.\n")
    proj_dir=os.path.dirname(os.path.abspath(fname))
    entries=[]
    if lower.endswith('.json') or data.strip().startswith('[') or data.strip().startswith('{'):
        try:
            j=json.loads(data)
        except Exception:
            raise CliError(f"cppcheck: error: failed to load project '{fname}'. An error occurred.\n")
        if isinstance(j,dict) and 'entries' in j: j=j['entries']
        if isinstance(j,list):
            for e in j:
                if not isinstance(e,dict): continue
                file_=e.get('file','')
                directory=e.get('directory',proj_dir)
                cmd=e.get('command','')
                args=e.get('arguments',[])
                # parse command for -D -I -U -std -x
                tokens=[]
                if cmd:
                    # simple shell split respecting quotes
                    import shlex
                    try: tokens=shlex.split(cmd)
                    except: tokens=cmd.split()
                elif args:
                    tokens=list(args)
                defines=[]; undefs=[]; incs=[]; language=None; std=None
                i=1 if tokens else 0
                while i < len(tokens):
                    t=tokens[i]
                    if t.startswith('-D') and len(t)>2: defines.append(t[2:])
                    elif t=='-D' and i+1<len(tokens): i+=1; defines.append(tokens[i])
                    elif t.startswith('-U') and len(t)>2: undefs.append(t[2:])
                    elif t=='-U' and i+1<len(tokens): i+=1; undefs.append(tokens[i])
                    elif t.startswith('-I') and len(t)>2: incs.append(t[2:])
                    elif t=='-I' and i+1<len(tokens): i+=1; incs.append(tokens[i])
                    elif t.startswith('--std=') or t.startswith('-std='): std=t.split('=',1)[1]
                    elif t=='-x' and i+1<len(tokens): i+=1; language=tokens[i]
                    elif t.startswith('-x') and len(t)>2: language=t[2:]
                    i+=1
                # file path as given relative to directory? display: cppcheck uses file as in json? In probe, file1.c display as "file1.c"
                entries.append({'filename':file_,'directory':directory,'defines':defines,'undefs':undefs,'includes':incs,'language':language,'std':std})
    elif lower.endswith('.cppcheck') or '<project' in data:
        # parse xml
        try:
            root=ET.fromstring(data)
        except Exception:
            raise CliError(f"cppcheck: error: failed to load project '{fname}'.\n")
        root_name=None
        for el in root.iter():
            if el.tag=='root' and 'name' in el.attrib: root_name=el.attrib['name']
            if el.tag=='importproject' and el.text:
                imp=el.text.strip()
                imp_path=imp if os.path.isabs(imp) else os.path.join(proj_dir,imp)
                _load_project(settings, imp_path)
                # project entries already added; continue
            if el.tag=='paths':
                for p in el:
                    if p.tag=='dir' and 'name' in p.attrib: settings.paths.append(p.attrib['name'])
                    if p.tag=='file' and 'name' in p.attrib: settings.paths.append(p.attrib['name'])
            if el.tag=='includedir':
                for p in el:
                    if 'name' in p.attrib: settings.includes.append(p.attrib['name'])
            if el.tag=='define':
                for p in el:
                    if 'name' in p.attrib: settings.defines.append(p.attrib['name'])
        if root_name and not entries and not settings.project_entries:
            settings.paths.append(root_name)
    elif lower.endswith('.sln'):
        # parse Project lines *.vcxproj
        for m in re.finditer(r'Project\("[^"]+"\)\s*=\s*"[^"]+",\s*"([^"]+\.vcxproj)"', data, re.I):
            vpath=m.group(1).replace('\\','/')
            vfull=vpath if os.path.isabs(vpath) else os.path.join(proj_dir,vpath)
            if os.path.isfile(vfull):
                _load_project_vcxproj(settings, vfull)
    elif lower.endswith('.vcxproj'):
        _load_project_vcxproj(settings, fname, data)
    elif lower.endswith('.bpr'):
        raise CliError(f"cppcheck: error: Borland C++ Builder 6 project is not supported.\n")
    else:
        # unknown project type: cppcheck message?
        # Check extension based handling: maybe treat as ... attempt json/xml else error
        raise CliError(f"cppcheck: error: failed to open project '{fname}'. The file is not a valid project file.\n")
    settings.project_entries.extend(entries)

def _load_project_vcxproj(settings, fname, data=None):
    proj_dir=os.path.dirname(os.path.abspath(fname))
    if data is None:
        data=open(fname,encoding='latin-1').read()
    # strip namespaces
    try:
        root=ET.fromstring(data)
    except Exception:
        return
    def local(tag): return tag.split('}')[-1]
    files=[]; incs=[]; defines=[]
    chosen_config=settings.project_configuration
    for el in root.iter():
        t=local(el.tag)
        if t in ('ClCompile','ClInclude') and 'Include' in el.attrib:
            files.append(el.attrib['Include'].replace('\\','/'))
        if t=='AdditionalIncludeDirectories' and el.text:
            for p in el.text.split(';'):
                if p.strip() and '%' not in p: incs.append(p.strip())
        if t=='PreprocessorDefinitions' and el.text:
            for d in el.text.split(';'):
                if d.strip() and '%' not in d: defines.append(d.strip())
    for f in files:
        # ignore headers? cppcheck includes only cpp sources? Include all as entries (headers will be filtered? unknown) keep just source ext
        ext=os.path.splitext(f)[1].lower()
        if ext in ('.cpp','.cxx','.cc','.c++','.c','.ipp','.ixx','.tpp','.txx','.cl','.C'.lower()):
            settings.project_entries.append({'filename':normalize_path(os.path.join(proj_dir,f)) if not os.path.isabs(f) else f,'directory':proj_dir,'defines':defines,'undefs':[],'includes':incs,'language':None,'std':None})

def parse_cli(argv):
    settings=Settings()
    # special first special token handling dealt by caller
    i=0
    n=len(argv)
    options_with_eq = [
        '--addon=','--addon-python=','--cppcheck-build-dir=','--check-level=','--checkers-report=','--clang=','--config-exclude=','--config-excludes-file=','--disable=','--enable=','--error-exitcode=','--exitcode-suppressions=','--file-filter=','--file-list=','--includes-file=','--include=','--language=','--library=','--max-configs=','--max-ctu-depth=','--output-file=','--output-format=','--platform=','--plist-output=','--project=','--project-configuration=','--relative-paths=','--report-type=','--rule=','--rule-file=','--showtime=','--std=','--suppress=','--suppressions-list=','--suppress-xml=','--template=','--template-location=','-rp=',
    ]
    def next_arg(optname, current=None):
        nonlocal i
        # For short options, cppcheck checks if next argv exists and doesn't start with '-'? Observed -j -1 gave missing, so if next missing or starts with '-' (?) Actually -j -1: -1 could be considered option-ish so missing. For -D -something? similar.
        if i+1>=n:
            raise CliError(f"cppcheck: error: argument to '{optname}' is missing.\n")
        nxt=argv[i+1]
        # cppcheck logic: if next token begins with '-', treat as missing for -j/-l etc, but for -D/-I/-U/-i/-x maybe same?
        # Test -I -foo would be missing? assume yes for all short missing checks
        if nxt.startswith('-') and nxt not in ('-',):
            # Special cases: -x has its own message handled by caller
            raise CliError(f"cppcheck: error: argument to '{optname}' is missing.\n")
        i+=1
        return argv[i]
    while i<n:
        arg=argv[i]
        # plain file/path
        if not arg.startswith('-') or arg=='-':
            if arg=='-':
                raise CliError('cppcheck: error: unrecognized command line option: "-".\n')
            settings.paths.append(arg)
            i+=1; continue
        # short / long exact flags
        if arg in ('-h','--help','--version','--errorlist'):
            # handled earlier, shouldn't reach
            i+=1; continue
        elif arg=='--check-config': settings.check_config=True
        elif arg=='--check-library': settings.check_library=True
        elif arg=='--dump': settings.dump=True
        elif arg=='-E': settings.E=True
        elif arg in ('-f','--force'):
            settings.force=True; settings.max_configs=1000000; settings.force_explicit_last='force'
        elif arg=='--fsigned-char': settings.fsigned_char=True
        elif arg=='--funsigned-char': settings.funsigned_char=True
        elif arg=='--inconclusive': settings.inconclusive=True
        elif arg=='--inline-suppr': settings.inline_suppr=True
        elif arg in ('-q','--quiet'): settings.quiet=True
        elif arg in ('-v','--verbose'): settings.verbose=True
        elif arg=='--xml': settings.xml=True; settings.output_format='xml'; settings.xml_version=2
        elif arg=='--safety':
            settings.safety=True; settings.enabled.add('information')
        elif arg=='--report-progress': settings.report_progress=True
        elif arg in ('-rp','--relative-paths'):
            settings.relative_paths=[]  # empty list means use path where files searched?
        elif arg=='--clang':
            settings.clang='clang'; settings.clang_exe='clang'
        elif arg=='-j':
            val=next_arg('-j'); num=_parse_int_arg('-j',val)
            if num<=0: raise CliError("cppcheck: error: argument for '-j' must be greater than 0.\n")
            settings.jobs=num
        elif arg.startswith('-j') and len(arg)>2:
            val=arg[2:]; num=_parse_int_arg('-j',val)
            if num<=0: raise CliError("cppcheck: error: argument for '-j' must be greater than 0.\n")
            settings.jobs=num
        elif arg=='-l':
            val=next_arg('-l'); num=_parse_int_arg('-l',val); settings.load=num
        elif arg.startswith('-l') and len(arg)>2 and arg[2].isdigit():
            settings.load=_parse_int_arg('-l',arg[2:])
        elif arg=='-I':
            val=next_arg('-I'); settings.includes.append(val)
        elif arg.startswith('-I') and len(arg)>2:
            settings.includes.append(arg[2:])
        elif arg=='-D':
            val=next_arg('-D'); _add_define_cli(settings,val)
        elif arg.startswith('-D') and len(arg)>2:
            _add_define_cli(settings,arg[2:])
        elif arg=='-U':
            val=next_arg('-U'); settings.undefines.append(val)
        elif arg.startswith('-U') and len(arg)>2:
            settings.undefines.append(arg[2:])
        elif arg=='-i':
            val=next_arg('-i'); settings.ignored.append(val)
        elif arg.startswith('-i') and len(arg)>2:
            settings.ignored.append(arg[2:])
        elif arg in ('-x',):
            # special missing message
            if i+1>=n or argv[i+1].startswith('-'):
                raise CliError("cppcheck: error: no language given to '-x' option.\n")
            i+=1; lang=argv[i]
            if lang not in ('c','c++'):
                raise CliError(f"cppcheck: error: unknown language '{lang}' enforced.\n")
            settings.language=lang
        elif any(arg.startswith(p) for p in options_with_eq):
            # dispatch by prefix (longest)
            prefix=max([p for p in options_with_eq if arg.startswith(p)], key=len)
            value=arg[len(prefix):]
            _handle_eq_option(settings,prefix,value)
        else:
            raise CliError(f'cppcheck: error: unrecognized command line option: "{arg}".\n')
        i+=1
    # post-validation (deferred platform)
    # project-configuration without VS project check: we need to know if project was VS. Our Settings store project str.
    if settings.project_configuration is not None:
        # if no project or project not sln/vcxproj -> error
        # Observed: --project-configuration=foo file1.c (no project) => error message above. Immediate or deferred? It occurred instead of checking.
        # We raise here (after parse). If project was a compile db, probably also no effect? assume same.
        is_vs=False
        if settings.project and (settings.project.lower().endswith('.sln') or settings.project.lower().endswith('.vcxproj')):
            is_vs=True
        if not is_vs:
            raise CliError("cppcheck: error: --project-configuration has no effect - no Visual Studio project provided.\n")
    _validate_platform(settings)
    if settings.plist_output is not None:
        # if plist output given and folder does not exist (empty string is treated as ?? observed empty proceeded file not found later, but that was missing file confusion. Check: empty path -> cppcheck: error: plist folder does not exist: ''. likely.
        if not os.path.isdir(settings.plist_output):
            raise CliError(f"cppcheck: error: plist folder does not exist: '{settings.plist_output}'.\n")
    if settings.cppcheck_build_dir is not None:
        if settings.cppcheck_build_dir=="":
            raise CliError("cppcheck: error: no path has been specified for --cppcheck-build-dir\n")
        if not os.path.isdir(settings.cppcheck_build_dir):
            raise CliError(f"cppcheck: error: Directory '{settings.cppcheck_build_dir}' specified by --cppcheck-build-dir argument has to be existent.\n")
    return settings

def _add_define_cli(settings, val):
    settings.defines.append(val)
    if '=' in val:
        k,v=val.split('=',1); settings.define_map[k]=v
    else:
        settings.define_map[val]='1'

def _validate_platform(settings):
    p=settings.platform_str
    if p=="":
        raise CliError("cppcheck: error: empty platform specified.\n")
    if p in BUILTIN_PLATFORMS:
        settings.platform_name=p; settings.sizes=dict(PLATFORM_SIZES.get(p,PLATFORM_SIZES['native'])); return
    # file path direct?
    exe_dir=get_exe_dir()
    cands=[]
    if os.path.isfile(p): cands.append(p)
    cands.append(os.path.join(exe_dir,'platforms',p+'.xml'))
    cands.append(os.path.join(FILESDIR,'platforms',p+'.xml'))
    for c in cands:
        if os.path.isfile(c):
            settings.platform_name='platformFile'; settings.platform_file=c
            # sizes: if name (basename without xml) known, use that; else try parse xml values
            base=os.path.basename(c)
            base_name=base[:-4] if base.endswith('.xml') else base
            sizes=dict(PLATFORM_SIZES.get(base_name, PLATFORM_SIZES.get(p, PLATFORM_SIZES['native'])))
            # parse xml bits if present
            try:
                root=ET.parse(c).getroot()
                mp={'char':'char','short':'short','int':'int','long':'long','long_long':'long long','float':'float','double':'double','long_double':'long double','pointer':'pointer','wchar_t':'wchar_t','size_t':'size_t'}
                for el in root.iter():
                    tag=el.tag
                    if tag.endswith('_bit'):
                        key=tag[:-4]
                        k=mp.get(key)
                        if k and el.text and el.text.strip().isdigit(): sizes[k]=int(el.text.strip())
            except Exception:
                pass
            settings.sizes=sizes; return
    raise CliError(f"cppcheck: error: unrecognized platform: '{p}'.\n")

def _handle_eq_option(settings, prefix, value):
    if prefix=='--enable=': _apply_enable(settings,value,'enable'); return
    if prefix=='--disable=': _apply_enable(settings,value,'disable'); return
    if prefix=='--std=':
        if value not in STD_MAP:
            raise CliError(f"cppcheck: error: unknown --std value '{value}'\n")
        lang,ver=STD_MAP[value]
        if lang=='c': settings.std_c=ver
        else: settings.std_cpp=ver
        return
    if prefix=='--platform=':
        if value=="": raise CliError("cppcheck: error: empty platform specified.\n")
        settings.platform_str=value; return
    if prefix=='--library=':
        if value=="": raise CliError("cppcheck: error: empty library specified.\n")
        settings.libraries.append(value); return
    if prefix=='--addon=': settings.addons.append(value); return
    if prefix=='--addon-python=': settings.addon_python=value; return
    if prefix=='--cppcheck-build-dir=':
        if value=="": raise CliError("cppcheck: error: no path has been specified for --cppcheck-build-dir\n")
        settings.cppcheck_build_dir=value; return
    if prefix=='--check-level=':
        if value not in ('reduced','normal','exhaustive'):
            raise CliError(f"cppcheck: error: unknown '--check-level' value '{value}'.\n")
        settings.check_level=value; return
    if prefix=='--checkers-report=': settings.checkers_report=value; return
    if prefix=='--clang=': settings.clang=value or 'clang'; settings.clang_exe=value or 'clang'; return
    if prefix=='--config-exclude=': settings.config_excludes.append(value); return
    if prefix=='--config-excludes-file=':
        try:
            lines=open(value,encoding='latin-1').read().splitlines()
        except Exception:
            raise CliError(f"cppcheck: error: unable to open config excludes file at '{value}'\n")
        for l in lines:
            if l.strip(): settings.config_excludes.append(l.strip())
        return
    if prefix=='--error-exitcode=':
        settings.error_exitcode=_parse_int_arg('--error-exitcode=',value); return
    if prefix=='--exitcode-suppressions=':
        _load_suppressions_list(settings,value,is_exitcode=True); return
    if prefix=='--file-filter=': settings.file_filters.append(value); return
    if prefix=='--file-list=':
        _load_file_list(settings,value,None); return
    if prefix=='--includes-file=':
        try:
            lines=open(value,encoding='latin-1').read().splitlines()
        except Exception:
            raise CliError(f"cppcheck: error: unable to open includes file at '{value}'\n")
        for l in lines:
            if l.strip(): settings.includes.append(l.strip())
        return
    if prefix=='--include=': settings.include_files.append(value); return
    if prefix=='--language=':
        if value not in ('c','c++'):
            raise CliError(f"cppcheck: error: unknown language '{value}' enforced.\n")
        settings.language=value; return
    if prefix=='--max-configs=':
        num=_parse_int_arg('--max-configs=',value)
        if num<=0: raise CliError("cppcheck: error: argument to '--max-configs=' must be greater than 0.\n")
        settings.max_configs=num; settings.max_configs_explicit=True; settings.force=False; settings.force_explicit_last='max-configs'; return
    if prefix=='--max-ctu-depth=':
        settings.max_ctu_depth=_parse_int_arg('--max-ctu-depth=',value); return
    if prefix=='--output-file=': settings.output_file=value; return
    if prefix=='--output-format=':
        if value not in ('text','sarif','xml','xmlv2','xmlv3'):
            raise CliError("cppcheck: error: argument to '--output-format=' must be 'text', 'sarif', 'xml' (deprecated), 'xmlv2' or 'xmlv3'.\n")
        settings.output_format=value
        if value in ('xml','xmlv2'): settings.xml=True; settings.xml_version=2
        elif value=='xmlv3': settings.xml=True; settings.xml_version=3
        return
    if prefix=='--plist-output=': settings.plist_output=value; return
    if prefix=='--project=':
        settings.project=value; _load_project(settings,value); return
    if prefix=='--project-configuration=': settings.project_configuration=value; return
    if prefix in ('--relative-paths=','-rp='):
        if value=="": raise CliError("cppcheck: error: no paths specified for the '-rp=' option.\n")
        parts=[p for p in value.split(';') if p!='']
        settings.relative_paths_list=parts; settings.relative_paths=parts; return
    if prefix=='--report-type=':
        valid=['normal','autosar','cert-c-2016','cert-cpp-2016','misra-c-2012','misra-c-2023','misra-c-2025','misra-cpp-2008','misra-cpp-2023']
        if value not in valid: raise CliError(f"cppcheck: error: Unknown report type '{value}'\n")
        settings.report_type=value; return
    if prefix=='--rule=': raise CliError("cppcheck: error: Option --rule cannot be used as Cppcheck has not been built with rules support.\n")
    if prefix=='--rule-file=': raise CliError("cppcheck: error: Option --rule-file cannot be used as Cppcheck has not been built with rules support.\n")
    if prefix=='--showtime=':
        if value not in ('none','file','file-total','summary','top5_file','top5_summary'):
            raise CliError(f"cppcheck: error: unrecognized --showtime mode: '{value}'. Supported modes: file, file-total, summary, top5_file, top5_summary.\n")
        settings.showtime=value; return
    if prefix=='--suppress=':
        settings.suppressions.append(parse_suppression_spec(value)); return
    if prefix=='--suppressions-list=':
        _load_suppressions_list(settings,value); return
    if prefix=='--suppress-xml=':
        _load_suppressions_xml(settings,value); return
    if prefix=='--template=': settings.template=value; settings.template_explicit=True; return
    if prefix=='--template-location=': settings.template_location=value; settings.template_location_explicit=(value!=""); return

