def _parse_int_arg(opt_display, val):
    # opt_display e.g. '-j' or '--error-exitcode='
    # integer parsing: allow negative? std::stoi like: leading spaces? digits with optional sign, trailing garbage invalid?
    # Observed abc -> not integer, =2 for -j -> "=2" not integer.
    s=val.strip()
    if not re.fullmatch(r'[+-]?\d+', s or ''):
        raise CliError(f"cppcheck: error: argument to '{opt_display}' is not valid - not an integer.\n")
    return int(s)

def _enable_expand(name):
    if name=='style': return {'style','warning','performance','portability'}
    if name=='all': return {'style','warning','performance','portability','information','unusedFunction','missingInclude'}
    return {name}

def _apply_enable(settings, value, kind):
    # kind enable/disable
    if value=="":
        raise CliError(f"cppcheck: error: --{kind} parameter is empty\n")
    parts=value.split(',')
    for p in parts:
        if p=="":
            raise CliError(f"cppcheck: error: --{kind}--enable parameter is empty\n")
        if p not in VALID_ENABLE:
            raise CliError(f"cppcheck: error: --{kind} parameter with the unknown name '{p}'\n")
        if kind=='enable':
            settings.enabled.update(_enable_expand(p))
        else:
            # disable: remove semantics stored in disabled set
            if p=='all':
                settings.disabled.update({'style','warning','performance','portability','information','unusedFunction','missingInclude'})
            else:
                settings.disabled.add(p)

def _load_suppressions_list(settings, fname, is_exitcode=False):
    try:
        with open(fname,'r',encoding='latin-1') as f:
            lines=f.read().splitlines()
    except Exception:
        raise CliError(f'cppcheck: error: couldn\'t open the file: "{fname}".\n')
    target = settings.exitcode_suppressions if is_exitcode else settings.suppressions
    for line in lines:
        if line=="" :
            continue
        if line.startswith('#') or line.startswith('//'):
            continue
        stripped=line
        # trailing comments? "id // trailing" - cppcheck strips ??? observed it worked: cut at " //"?
        # But a line like "invalid ... with spaces" should raise invalid id with whole line. So only strip if second token starts with // or #?
        # implementation: if ' //' in line, cut before it; if ' #' - maybe not.
        if ' //' in stripped:
            stripped=stripped.split(' //',1)[0]
        if stripped=="" :
            continue
        sup=parse_suppression_spec(stripped)
        target.append(sup)

def _load_suppressions_xml(settings, fname):
    # tinyxml error codes naming
    if not os.path.isfile(fname):
        raise CliError(f"cppcheck: error: failed to load suppressions XML '{fname}' (XML_ERROR_FILE_NOT_FOUND).\n")
    try:
        tree=ET.parse(fname)
    except ET.ParseError as e:
        # differentiate empty / parsing text?
        try:
            content=open(fname,'rb').read()
        except:
            content=b''
        if len(content.strip())==0:
            code="XML_ERROR_EMPTY_DOCUMENT"
        else:
            code="XML_ERROR_PARSING_TEXT"
        raise CliError(f"cppcheck: error: failed to load suppressions XML '{fname}' ({code}).\n")
    root=tree.getroot()
    for sup_el in root.iter('suppress'):
        id_=''; fname2=''; line=None; symbol=None
        for child in sup_el:
            txt=(child.text or '')
            if child.tag=='id': id_=txt
            elif child.tag in ('fileName','file'): fname2=txt
            elif child.tag in ('lineNumber','line'):
                try: line=int(txt)
                except: line=None
            elif child.tag=='symbolName': symbol=txt
        if not id_:
            raise CliError("cppcheck: error: Failed to add suppression. No id.\n")
        if re.search(r'[^A-Za-z0-9_\*\?]', id_):
            raise CliError(f'cppcheck: error: Failed to add suppression. Invalid id "{id_}"\n')
        settings.suppressions.append(Suppression(id_,fname2,line,symbol))

def _load_file_list(settings, fname, stdin_data_holder):
    if fname=='-':
        data=sys.stdin.buffer.read().decode('latin-1')
        lines=data.splitlines()
    else:
        try:
            lines=open(fname,encoding='latin-1').read().splitlines()
        except Exception:
            raise CliError(f'cppcheck: error: couldn\'t open the file: "{fname}".\n')
    for line in lines:
        line=line.strip()
        if not line: continue
        # comment lines? observed # comment in list was ignored because file not found maybe; keep as path if starts with #? It resulted in 2 files, so either ignored as nonexistent path. We'll add as path and later nonexistent paths are ignored if some exist. That matches behaviour.
        settings.paths.append(line)

def _load_project(settings, fname):
    if not os.path.isfile(fname):
        # failed to open project 'x'. The file does not exist.
        raise CliError(f"cppcheck: error: failed to open project '{fname}'. The file does not exist.\n")
    # determine type by extension/content
    lower=fname.lower()
    try:
        data=open(fname,'rb').read().decode('latin-1')
    except Exception:
        raise CliError(f"cppcheck: error: failed to open project '{fname}'. The file does not exist.\n")
    proj_dir=os.path.dirname(os.path.abspath(fname))
    entries=[]
    if lower.endswith('.json') or data.strip().startswith('[') or data.strip().startswith('{'):
        try:
            j=json.loads(data)
        except Exception:
            raise CliError(f"cppcheck: error: failed to load project '{fname}'. An error occurred.\n")
        if isinstance(j,dict) and 'entries' in j: j=j['entries']
        if isinstance(j,list):
            for e in j:
                if not isinstance(e,dict): continue
                file_=e.get('file','')
                directory=e.get('directory',proj_dir)
                cmd=e.get('command','')
                args=e.get('arguments',[])
                # parse command for -D -I -U -std -x
                tokens=[]
                if cmd:
                    # simple shell split respecting quotes
                    import shlex
                    try: tokens=shlex.split(cmd)
                    except: tokens=cmd.split()
                elif args:
                    tokens=list(args)
                defines=[]; undefs=[]; incs=[]; language=None; std=None
                i=1 if tokens else 0
                while i < len(tokens):
                    t=tokens[i]
                    if t.startswith('-D') and len(t)>2: defines.append(t[2:])
                    elif t=='-D' and i+1<len(tokens): i+=1; defines.append(tokens[i])
                    elif t.startswith('-U') and len(t)>2: undefs.append(t[2:])
                    elif t=='-U' and i+1<len(tokens): i+=1; undefs.append(tokens[i])
                    elif t.startswith('-I') and len(t)>2: incs.append(t[2:])
                    elif t=='-I' and i+1<len(tokens): i+=1; incs.append(tokens[i])
                    elif t.startswith('--std=') or t.startswith('-std='): std=t.split('=',1)[1]
                    elif t=='-x' and i+1<len(tokens): i+=1; language=tokens[i]
                    elif t.startswith('-x') and len(t)>2: language=t[2:]
                    i+=1
                # file path as given relative to directory? display: cppcheck uses file as in json? In probe, file1.c display as "file1.c"
                entries.append({'filename':file_,'directory':directory,'defines':defines,'undefs':undefs,'includes':incs,'language':language,'std':std})
    elif lower.endswith('.cppcheck') or '<project' in data:
        # parse xml
        try:
            root=ET.fromstring(data)
        except Exception:
            raise CliError(f"cppcheck: error: failed to load project '{fname}'.\n")
        root_name=None
        for el in root.iter():
            if el.tag=='root' and 'name' in el.attrib: root_name=el.attrib['name']
            if el.tag=='importproject' and el.text:
                imp=el.text.strip()
                imp_path=imp if os.path.isabs(imp) else os.path.join(proj_dir,imp)
                _load_project(settings, imp_path)
                # project entries already added; continue
            if el.tag=='paths':
                for p in el:
                    if p.tag=='dir' and 'name' in p.attrib: settings.paths.append(p.attrib['name'])
                    if p.tag=='file' and 'name' in p.attrib: settings.paths.append(p.attrib['name'])
            if el.tag=='includedir':
                for p in el:
                    if 'name' in p.attrib: settings.includes.append(p.attrib['name'])
            if el.tag=='define':
                for p in el:
                    if 'name' in p.attrib: settings.defines.append(p.attrib['name'])
        if root_name and not entries and not settings.project_entries:
            settings.paths.append(root_name)
    elif lower.endswith('.sln'):
        # parse Project lines *.vcxproj
        for m in re.finditer(r'Project\("[^"]+"\)\s*=\s*"[^"]+",\s*"([^"]+\.vcxproj)"', data, re.I):
            vpath=m.group(1).replace('\\','/')
            vfull=vpath if os.path.isabs(vpath) else os.path.join(proj_dir,vpath)
            if os.path.isfile(vfull):
                _load_project_vcxproj(settings, vfull)
    elif lower.endswith('.vcxproj'):
        _load_project_vcxproj(settings, fname, data)
    elif lower.endswith('.bpr'):
        raise CliError(f"cppcheck: error: Borland C++ Builder 6 project is not supported.\n")
    else:
        # unknown project type: cppcheck message?
        # Check extension based handling: maybe treat as ... attempt json/xml else error
        raise CliError(f"cppcheck: error: failed to open project '{fname}'. The file is not a valid project file.\n")
