    F('sscanf',args={1:A(not_null=True,not_uninit=True,strz=True),2:A(formatstr=True,scan=True),'any':A()})
    F('exit',noreturn=True,args={1:A(not_uninit=True)})
    F('_Exit',noreturn=True,args={1:A(not_uninit=True)})
    F('_exit',noreturn=True,args={1:A(not_uninit=True)})
    F('abort',noreturn=True)
    F('assert',args={1:A()})
    F('abs',use_retval=True,args={1:A(not_uninit=True)})
    F('atoi',use_retval=True,args={1:A(not_null=True,not_uninit=True,strz=True)})
    F('atol',use_retval=True,args={1:A(not_null=True,not_uninit=True,strz=True)})
    F('atof',use_retval=True,args={1:A(not_null=True,not_uninit=True,strz=True)})
    # posix-like commonly in std too (?) open/close are in posix cfg; we add when posix library loaded in _apply_named_library_extras
    return lib

def _apply_named_library_extras(lib, name):
    # Called when a library cfg file for known names is successfully found (or builtin placeholders generated).
    # Adds knowledge that real cfg files would contain, to approximate proper installation.
    def A(**kw):
        d={'not_null':False,'not_uninit':False,'strz':False,'formatstr':False,'scan':None,'minsize':None,'direction':None}; d.update(kw); return d
    def F(n,**kw):
        fn=lib.functions.get(n) or LibFunction(n)
        fn.noreturn=kw.get('noreturn',fn.noreturn); fn.use_retval=kw.get('use_retval',fn.use_retval)
        if 'args' in kw: fn.args.update(kw['args'])
        lib.functions[n]=fn
    if name in ('posix','gnu'):
        lib.alloc['open']={'kind':'open','init':True,'group':'resource-fd'}
        lib.dealloc['close']='resource-fd'
        lib.alloc['socket']={'kind':'socket','init':True,'group':'resource-fd'}
        lib.alloc['opendir']={'kind':'opendir','init':True,'group':'resource-dir'}
        lib.dealloc['closedir']='resource-dir'
        F('open',use_retval=True,args={1:A(not_uninit=True,strz=True)})
        F('close',args={1:A(not_uninit=True)})
        F('read',args={1:A(not_uninit=True),2:A(direction='out'),3:A(not_uninit=True)})
        F('write',args={1:A(not_uninit=True),2:A(not_uninit=True),3:A(not_uninit=True)})
    if name=='windows':
        pass

def find_library_file(libname, exe_dir):
    # returns path or None
    if os.path.isfile(libname):
        return libname
    # try exe/cfg and FILESDIR/cfg
    candidates=[]
    if libname.endswith('.cfg'):
        candidates=[os.path.join(exe_dir,'cfg',libname), os.path.join(FILESDIR,'cfg',libname)]
    else:
        candidates=[os.path.join(exe_dir,'cfg',libname+'.cfg'), os.path.join(FILESDIR,'cfg',libname+'.cfg'), os.path.join(exe_dir,'cfg',libname), os.path.join(FILESDIR,'cfg',libname)]
    for c in candidates:
        if os.path.isfile(c): return c
    return None

def load_library_file(lib, path, display_name, is_std=False):
    # returns error string for stdout or None. Mutates lib with definitions from file (best effort)
    try:
        data=open(path,'rb').read()
    except Exception:
        return None
    if len(data.strip())==0:
        # tinyxml message first for non-std? For std? Earlier empty custom file gave tinyxml line. For std empty? assume same then failed+broken line.
        lines=[]
        lines.append("Error=XML_ERROR_EMPTY_DOCUMENT ErrorID=13 (0xd) Line number=0\n")
        lines.append(f"cppcheck: Failed to load library configuration file '{display_name}'. Bad XML\n")
        if is_std: lines.append('Failed to load std.cfg. Your Cppcheck installation is broken, please re-install. The Cppcheck binary was compiled with FILESDIR set to "/usr/local/share/Cppcheck" and will therefore search for std.cfg in /usr/local/share/Cppcheck/cfg.\n')
        return ''.join(lines)
    try:
        root=ET.fromstring(data)
    except ET.ParseError as e:
        # position / line
        lineno=1
        try:
            lineno=e.position[0]
        except Exception: pass
        lines=[f"Error=XML_ERROR_PARSING_TEXT ErrorID=8 (0x8) Line number={lineno}\n", f"cppcheck: Failed to load library configuration file '{display_name}'. Bad XML\n"]
        if is_std: lines.append('Failed to load std.cfg. Your Cppcheck installation is broken, please re-install. The Cppcheck binary was compiled with FILESDIR set to "/usr/local/share/Cppcheck" and will therefore search for std.cfg in /usr/local/share/Cppcheck/cfg.\n')
        return ''.join(lines)
    # Validate minsize etc, collect unknown tags
    unknown=set()
    known={'def','memory','resource','alloc','dealloc','function','arg','noreturn','returnValue','use-retval','leak-ignore','not-null','not-uninit','strz','formatstr','minsize','define','podtype','undefine','markup','container','size','ignorefunction','unignorefunction','group','iterator','type','allocinit','string','inherits','member','access','deallocbuffer','realloc','detect','exporter','reflection','smart-pointer','windowhandle'}
    # Validate
    for el in root.iter():
        if el.tag not in known and el.tag not in KNOWN_LIB_TAGS:
            unknown.add(el.tag)
        if el.tag=='minsize':
            t=el.get('type')
            if t is None:
                return _lib_fail(display_name, "Missing attribute 'type'", is_std)
            if t not in ('value','argvalue','strlen','sizeof','elementsize'):
                return _lib_fail(display_name, f"Bad attribute value '{t}'", is_std)
            if t=='value' and el.get('value') is None:
                return _lib_fail(display_name, "Missing attribute 'value'", is_std)
            if t in ('argvalue','strlen') and el.get('arg') is None:
                return _lib_fail(display_name, "Missing attribute 'arg'", is_std)
    if unknown:
        lib.unknown_messages.append(f"cppcheck: Found unknown elements in configuration file '{display_name}': {', '.join(sorted(unknown))}\n")
    # Parse
    for child in root:
        if child.tag=='define':
            n=child.get('name'); v=child.get('value')
            if n is not None: lib.defines[n]= v if v is not None else ''
        elif child.tag=='podtype':
            n=child.get('name'); s=child.get('size')
            if n:
                try: lib.podtypes[n]=int(s) if s else None
                except: lib.podtypes[n]=None
        elif child.tag in ('memory','resource'):
            grp = 'memory' if child.tag=='memory' else 'resource-file'
            # Need map alloc->group more precise: for resource, all allocs in same resource element share group? Real cfg has multiple <resource> blocks each with alloc/dealloc pairs.
            # We'll create group name based on first dealloc? store temporarily then assign.
            allocs=[]; deallocs=[]
            for sub in child:
                name=(sub.text or '').strip()
                if not name: continue
                if sub.tag=='alloc':
                    init=sub.get('init')
                    initv=True if init=='true' else False if init=='false' else None
                    allocs.append((name,initv))
                elif sub.tag=='dealloc': deallocs.append(name)
            # group id: if dealloc present use dealloc name as group key else grp
            # For memory, kind malloc for classic names; else kind = alloc name
            for name,initv in allocs:
                kind='malloc' if child.tag=='memory' else name
                if name in lib.alloc and child.tag=='memory':
                    kind=lib.alloc[name]['kind']
                lib.alloc[name]={'kind':kind,'init':initv if initv is not None else lib.alloc.get(name,{}).get('init'),'group': deallocs[0] if deallocs else grp}
            for name in deallocs:
                lib.dealloc[name]= allocs[0][0] if False else (lib.alloc[allocs[0][0]]['group'] if allocs else grp)
                # ensure group matching: set dealloc group to same string as alloc group's value (dealloc name for resource pairs) ??? Simplification: use first dealloc as group id for allocs and dealloc maps to that id
                lib.dealloc[name]= name if child.tag!='memory' else 'memory'
                if child.tag=='memory':
                    for an,_ in allocs: lib.alloc[an]['group']='memory'
                else:
                    for an,_ in allocs: lib.alloc[an]['group']=name
        elif child.tag=='function':
            names_attr=child.get('name') or ''
            for fname in [x.strip() for x in names_attr.split(',') if x.strip()]:
                fn=lib.functions.get(fname) or LibFunction(fname)
                for sub in child:
                    if sub.tag=='noreturn':
                        txt=(sub.text or '').strip().lower()
                        fn.noreturn = (txt=='true')
                    elif sub.tag=='use-retval': fn.use_retval=True
                    elif sub.tag=='leak-ignore': fn.leak_ignore=True
                    elif sub.tag=='returnValue': fn.return_type=sub.get('type') or (sub.text or '').strip() or fn.return_type
                    elif sub.tag=='arg':
                        nr=sub.get('nr')
                        try: key=int(nr) if nr and nr.isdigit() else ('any' if nr=='any' else nr)
                        except: key=nr
                        a={'not_null':False,'not_uninit':False,'strz':False,'formatstr':False,'scan':None,'minsize':None,'direction':sub.get('direction')}
                        for aa in sub:
                            if aa.tag=='not-null': a['not_null']=True
                            elif aa.tag=='not-uninit': a['not_uninit']=True
                            elif aa.tag=='strz': a['strz']=True
                            elif aa.tag=='formatstr':
                                a['formatstr']=True
                                scan=aa.get('scan')
                                if scan is not None: a['scan']=(scan=='true')
                            elif aa.tag=='minsize':
                                mt=aa.get('type'); marg=aa.get('arg'); mval=aa.get('value')
                                if mt=='value':
                                    try: a['minsize']=('value',int(mval))
                                    except: pass
                                elif mt in ('argvalue','strlen'):
                                    try: a['minsize']=(mt,int(marg))
                                    except: pass
                                elif mt: a['minsize']=(mt,marg)
                        if key is not None: fn.args[key]=a
                lib.functions[fname]=fn
    return None

def _lib_fail(display_name, reason, is_std):
    s=f"cppcheck: Failed to load library configuration file '{display_name}'. {reason}\n"
    if is_std: s+='Failed to load std.cfg. Your Cppcheck installation is broken, please re-install. The Cppcheck binary was compiled with FILESDIR set to "/usr/local/share/Cppcheck" and will therefore search for std.cfg in /usr/local/share/Cppcheck/cfg.\n'
    return s

def load_libraries(settings):
    # Returns (lib, error_stdout_str_or_None)
    exe_dir=get_exe_dir()
    lib=builtin_library()
    # std.cfg is always loaded, lookup by name 'std.cfg'
    std_path=find_library_file('std.cfg', exe_dir)
    if not std_path:
        return lib, ("cppcheck: Failed to load library configuration file 'std.cfg'. File not found\n" 'Failed to load std.cfg. Your Cppcheck installation is broken, please re-install. The Cppcheck binary was compiled with FILESDIR set to "/usr/local/share/Cppcheck" and will therefore search for std.cfg in /usr/local/share/Cppcheck/cfg.\n')
    err=load_library_file(lib, std_path, 'std.cfg', is_std=True)
    if err: return lib, err
    for name in settings.libraries:
        # library names may be comma separated? cppcheck --library=a,b ? unknown, treat as single.
        p=find_library_file(name, exe_dir)
        if not p:
            return lib, f"cppcheck: Failed to load library configuration file '{name}'. File not found\n"
        err=load_library_file(lib, p, name, is_std=False)
        if err: return lib, err
        base=name
        if base.endswith('.cfg'): base=base[:-4]
        base=os.path.basename(base)
        _apply_named_library_extras(lib, base)
    return lib, None

def find_addon(settings, addon):
    # returns (found_cmd_path, error_stdout or None)
    if addon.endswith('.json'):
        # search file as is and in addons dir
        exe_dir=get_exe_dir()
        cands=[addon, os.path.join(exe_dir,'addons',os.path.basename(addon)), os.path.join(FILESDIR,'addons',os.path.basename(addon))]
        for c in cands:
            if os.path.isfile(c): return ('json',c)
        return (None, f"Failed to open {addon}\n")
    name_py = addon if addon.endswith('.py') else addon+'.py'
    exe_dir=get_exe_dir()
    if os.path.isfile(name_py):
        return ('script', name_py)
    # exe addons
    cand=os.path.join(exe_dir,'addons',os.path.basename(name_py))
    if os.path.isfile(cand):
        return ('script', cand)
    cand2=os.path.join(FILESDIR,'addons',os.path.basename(name_py))
    if os.path.isfile(cand2):
        return ('script', cand2)
    cand3=os.path.join(exe_dir, os.path.basename(name_py))
    if os.path.isfile(cand3):
        return ('script', cand3)
    return (None, f"Did not find addon {name_py}\n")

