    def loc(self,info=''):
        return Loc(self.file,self.line,self.col,info)
    def copy_with_loc(self, other):
        t=Token(self.s, other.file, other.line, other.col, self.kind, self.str_value, self.char_value); t.num_value=self.num_value; return t
    def __repr__(self):
        return f"Tok({self.s!r}@{self.line}:{self.col})"

