def decode_escape(s, i):
    # s[i] == '\\'
    if i+1>=len(s): return ('', i+1)
    c=s[i+1]
    mp={'n':'\n','t':'\t','r':'\r','0':'\0','a':'\a','b':'\b','f':'\f','v':'\v','\\':'\\','"':'"',"'":"'",'?':'?'}
    if c in mp and not (c=='0' and i+2<len(s) and s[i+2].isdigit()):
        return (mp[c], i+2)
    if c=='x':
        j=i+2; hexs=''
        while j<len(s) and s[j] in '0123456789abcdefABCDEF': hexs+=s[j]; j+=1
        if hexs:
            try: return (chr(int(hexs,16)&0xFF), j)
            except: return ('',j)
        return ('x',i+2)
    if c in '01234567':
        j=i+1; octs=''
        while j<len(s) and j<i+4 and s[j] in '01234567': octs+=s[j]; j+=1
        try: return (chr(int(octs,8)&0xFF),j)
        except: return ('',j)
    if c=='u' and i+5<len(s)+1:
        try: return (chr(int(s[i+2:i+6],16)), i+6)
        except: return ('',i+2)
    if c=='U':
        try: return (chr(int(s[i+2:i+10],16)), i+10)
        except: return ('',i+2)
    return (c,i+2)

