    # raw string?
    # handled by caller with str_value preset
    content=''
    i=idx+1
    while i<len(raw):
        c=raw[i]
        if c=='"': break
        if c=='\\':
            ch,i2=decode_escape(raw,i); content+=ch; i=i2; continue
        content+=c; i+=1
    return content

def decode_char_content(raw):
    idx=raw.find("'")
    if idx<0: return None
    i=idx+1
    vals=[]
    while i<len(raw):
