def evaluate_preprocessor_expr(tokens, macros, settings, language):
    # Process defined and macro expansion then evaluate.
    # Replace defined manually inside evaluator would work if tokens not expanded for macros used in defined(). But if we expand first, defined(X) might expand X. So evaluator handles defined before macro expansion? We'll do a preprocessing pass: expand macros except skip argument of defined.
    # Approach: create token list where defined(...) is replaced by 1/0 token, other tokens macro expanded.
    out=[]
    i=0
    while i < len(tokens):
        t=tokens[i]
        if t.s=='defined':
            # parse
            name=None; j=i+1
            if j < len(tokens) and tokens[j].s=='(':
                if j+1 < len(tokens): name=tokens[j+1].s
                j+=3 if j+2 < len(tokens) and tokens[j+2].s==')' else 2
            elif j < len(tokens):
                name=tokens[j].s; j+=1
            else:
                j+=1
            val='1' if (name in macros) else '0'
            out.append(Token(val,t.file,t.line,t.col,'num')); i=j; continue
        out.append(t); i+=1
    # Now macro expand (object and function). For macros defined as empty, expansion removes token; in #if context a defined empty macro identifier should become 1? If entire expr becomes empty, return 0? For "#if A" where A defined empty via config 'A', expand -> empty -> we treat as 1 (to take branch). Detect: if original out tokens are single identifier which is empty macro, return 1.
    if len(out)==1 and out[0].kind=='id' and out[0].s in macros and not macros[out[0].s].body:
        return 1
    expanded=expand_tokens(out, macros)
    if not expanded:
        return 0
    v=eval_const_expr(expanded, macros, settings, var_values={}, language=language, in_preprocessor=True)
    return v

