    __slots__=('display','real','extra_defines','extra_undefs','extra_includes','language','std')
    def __init__(self,display,real,extra_defines=None,extra_undefs=None,extra_includes=None,language=None,std=None):
        self.display=display; self.real=real; self.extra_defines=extra_defines or []; self.extra_undefs=extra_undefs or []; self.extra_includes=extra_includes or []; self.language=language; self.std=std

def determine_language(display, settings, entry=None):
    if entry and entry.language:
        lang=entry.language
        return 'c++' if lang in ('c++','cpp','cplusplus','c-plus-plus') else 'c'
    if settings and settings.language:
        return settings.language
    ext=display.rsplit('.',1)[-1].lower() if '.' in os.path.basename(display) else ''
    # Preserve case for .C
    if display.endswith('.C'):
        return 'c++'
    if ext in ('c','h','cl'):
        return 'c'
    if ext in ('cpp','cxx','cc','c++','tpp','txx','ipp','ixx','hh','hpp','hxx','h++','cu'):
        return 'c++'
    # unknown default C++
    return 'c++'

class Analyzer:
    def __init__(self, settings, lib):
        self.settings=settings; self.lib=lib
        self.file_cache={}  # (real,display) -> tokenize result
        self.file_lines={}  # display -> lines
        self.file_real_by_display={} # display -> real
        self.inline_suppressions=[]
        self.inline_collected_files=set()
        self.invalid_suppression_errors=[]
        self.unhandled_by_file={}  # display -> (code,line,col) first
        self.syntax_token_errors_by_file={}
        self.raw_files_order=[] # displays in order first tokenized for dumps
        self.critical_ids=set()
    def register_file(self, display, real):
        if display not in self.file_lines:
            try:
                data=open(real,'rb').read().decode('latin-1')
            except Exception:
                data=''
            self.file_lines[display]=data.split('\n')
            self.file_real_by_display[display]=real
        return self.file_lines[display]
    def tokenize(self, display, real):
        key=(os.path.realpath(real),display)
        if key in self.file_cache:
            return self.file_cache[key]
        try:
            text=open(real,'rb').read().decode('latin-1')
        except Exception:
            text=''
        self.register_file(display,real)
        if display not in self.raw_files_order:
            self.raw_files_order.append(display)
        raw_lines, comments, unhandled, tokerrs = tokenize_file_text(text, display)
        res={'raw_lines':raw_lines,'comments':comments,'unhandled':unhandled,'tokerrs':tokerrs,'text':text}
        self.file_cache[key]=res
        if unhandled and display not in self.unhandled_by_file:
            self.unhandled_by_file[display]=unhandled
        if tokerrs and display not in self.syntax_token_errors_by_file:
            self.syntax_token_errors_by_file[display]=tokerrs
        # inline suppressions
        if self.settings.inline_suppr and key not in self.inline_collected_files:
            self.inline_collected_files.add(key)
            self._collect_inline_suppressions(display, comments)
        return res
    def _collect_inline_suppressions(self, display, comments):
        # comments text excludes // or /* */
        open_blocks=[] # not global? per file collection, need handle begin/end within file - process sequentially here with local list and finalize
        pending_begin=[]
        for c in comments:
            text=c['text']
            # Find cppcheck-suppress occurrences in comment
            # Patterns: cppcheck-suppress, cppcheck-suppress-begin, cppcheck-suppress-end
            idx=0
            while True:
                m=re.search(r'cppcheck-suppress(-begin|-end)?\b', text[idx:])
                if not m: break
                pos=idx+m.start(); kind=m.group(1) or ''
                rest=text[pos+len(m.group(0)):].strip()
                # rest up to newline
                rest=rest.split('\n',1)[0].strip()
                # split by ; or // comment comment separator
                # Valid attributes after id: tokens like symbolName=sym ; or // comment
                if ';' in rest: rest_main=rest.split(';',1)[0].strip()
                elif '//' in rest: rest_main=rest.split('//',1)[0].strip()
                else: rest_main=rest
                parts=rest_main.split()
                if not parts:
                    idx=pos+1; continue
                id_=parts[0]
                # Validate extra parts: if more than one part and any part does not contain '=', then invalid suppression error with first bad attr
                symbol=None; bad=None
                for p in parts[1:]:
                    if p.startswith('symbolName='):
                        symbol=p[len('symbolName='):]
                    else:
                        bad=p; break
                if bad is not None:
                    loc=Loc(display,c['line_start'],1,'')
                    err=Error('invalidSuppression','error',f"Bad suppression attribute '{bad}'. You can write comments in the comment after a ; or //. Valid suppression attributes; symbolName=sym",[loc],rank=rank_for('invalidSuppression'))
                    self.invalid_suppression_errors.append(err)
                target_line = c['line_start'] if c['has_code_before'] else c['line_end']+1
                if kind=='-begin':
                    pending_begin.append((id_,symbol,c['line_end']+1))
                elif kind=='-end':
                    # close matching begin
                    for (bid,bsym,bline) in pending_begin:
                        if bid==id_:
                            sup=Suppression(id_,display,bline,bsym,is_inline=True,extra={'line_end':c['line_start']-1,'suppr_line':bline-1})
                            self.inline_suppressions.append(sup)
                    pending_begin=[x for x in pending_begin if x[0]!=id_]
                else:
                    sup=Suppression(id_,display,target_line,symbol,is_inline=True,extra={'suppr_line':c['line_start']})
                    self.inline_suppressions.append(sup)
                idx=pos+ len(m.group(0))
        # Unclosed begin: suppress until end of file? Create with line_end=1e9
        for (bid,bsym,bline) in pending_begin:
            self.inline_suppressions.append(Suppression(bid,display,bline,bsym,is_inline=True,extra={'line_end':10**9,'suppr_line':bline-1}))

class PreprocResult:
    __slots__=('tokens','errors','critical','configs_used','raw_files','directives')
    def __init__(self):
        self.tokens=[]; self.errors=[]; self.critical=False; self.directives=[]

def _initial_macros(analyzer, entry, language, config_items):
    settings=analyzer.settings; lib=analyzer.lib
    macros={}
    # library defines (NULL etc). In C++, NULL still 0, true/false are keywords not macros - lib defines include true/false added by us; avoid defining true/false for C++? For C, include <stdbool> defines them, but without header cppcheck may treat true/false as bool keywords anyway. Remove true/false macros to avoid expansion distorting type bool keywords; they are in lib.defines - skip those.
    for name,val in lib.defines.items():
        if name in ('true','false'): continue
        dummy=Token(name,'',0,0,'id')
        macros[name]=make_macro_from_value(name,val,dummy)
    if language=='c++':
        stdver=analyzer.settings.std_cpp
        vmap={'c++03':'199711L','c++11':'201103L','c++14':'201402L','c++17':'201703L','c++20':'202002L','c++23':'202302L','c++26':'202400L'}
        macros['__cplusplus']=make_macro_from_value('__cplusplus', vmap.get(stdver,'202002L'), Token('__cplusplus','',0,0,'id'))
    # project defines then CLI
    for d in (entry.extra_defines or []):
        _apply_define_str(macros,d)
    for d in settings.defines:
        _apply_define_str(macros,d)
    # undefs
    for u in (entry.extra_undefs or []):
        macros.pop(u,None)
    for u in settings.undefines:
        macros.pop(u,None)
    # config items: list of strings NAME or NAME=value, already excluding user defines as parameters perhaps
    for item in (config_items or []):
        if '=' in item:
            n,v=item.split('=',1); macros[n]=make_macro_from_value(n,v,Token(n,'',0,0,'id'))
        else:
            macros[item]=Macro(item,None,[],False)
    # Re-apply undefs again? A config item for a user-undefined symbol should not occur (discovery skips). If project defines etc conflict - keep config.
    return macros

def _apply_define_str(macros, d):
    if '=' in d:
        n,v=d.split('=',1)
        if n: macros[n]=make_macro_from_value(n,v,Token(n,'',0,0,'id'))
    else:
        if d: macros[d]=make_macro_from_value(d,'1',Token(d,'',0,0,'id'))

class _TUState:
    def __init__(self, analyzer, entry, language, config_items):
        self.analyzer=analyzer; self.entry=entry; self.language=language
        self.macros=_initial_macros(analyzer,entry,language,config_items)
        self.tokens=[]
        self.errors=[]
        self.pending=[]  # tokens pending macro expansion in current file process chain
        self.include_stack=[] # realpaths
        self.pragma_once=set()
        self.critical=False
        self.directives=[]
        self.force_include_failed=False
    def flush_pending(self):
        if not self.pending: return
        # Handle __LINE__/__FILE__ special replacements before macro expansion
        pend=[]
        for t in self.pending:
            if t.kind=='id' and t.s=='__LINE__':
                pend.append(Token(str(t.line),t.file,t.line,t.col,'num'))
            elif t.kind=='id' and t.s=='__FILE__':
                esc=t.file.replace('\\','\\\\').replace('"','\\"')
                pend.append(Token('"'+esc+'"',t.file,t.line,t.col,'string',str_value=t.file))
            else:
                pend.append(t)
        expanded=expand_tokens(pend, self.macros)
        self.tokens.extend(expanded)
        self.pending=[]
    def process_entry(self):
        # force includes
        for inc in self.analyzer.settings.include_files:
            # find file as path relative cwd (or as given)
            if os.path.isfile(inc):
                disp=normalize_path(inc)
                self.process_file(disp, inc, is_include=True)
            else:
                # replicate weird internal error
                loc=Loc(self.entry.display,0,0,'')
                err=Error('internalError','error',f"Bailing out from analysis: Checking file failed: unexpected simplecpp::Output type 7",[loc],rank=rank_for('internalError'),critical=True)
                self.errors.append(err); self.analyzer.critical_ids.add('internalError'); self.critical=True
                raise BailoutTU()
        for inc in (self.entry.extra_includes or []):
            # project forced includes unknown, skip if missing?
            if os.path.isfile(inc):
                self.process_file(normalize_path(inc),inc,is_include=True)
        self.process_file(self.entry.display, self.entry.real, is_include=False)
        self.flush_pending()
    def process_file(self, display, real, is_include=False):
        real_abs=os.path.realpath(real)
        if real_abs in self.pragma_once:
            return
        if real_abs in self.include_stack:
            # recursive include - skip to prevent infinite (simplecpp would loop/error, but guard usually handles)
            return
        if len(self.include_stack)>=100:
            return
        res=self.analyzer.tokenize(display, real)
        # unhandled / syntax token errors are handled at TU level by caller before analysis (global). But if included file has them, they should bail TU. Collector in analyzer global; here check if this file has tokerrs - create syntax error and bail
        # We'll handle in preprocess_tu wrapper before process? Easier: if tokerrs present, raise with errors appended.
        if res['tokerrs']:
            for (quote,f,line,col) in res['tokerrs'][:1]:
                loc=Loc(f,line,col,'')
                err=Error('syntaxError','error',f"No pair for character ({quote}). Can't process file. File is either invalid or unicode, which is currently not supported.",[loc],rank=rank_for('syntaxError'),critical=True)
                self.errors.append(err); self.analyzer.critical_ids.add('syntaxError'); self.critical=True
            raise BailoutTU()
        # unhandled char handled at wrapper pre-check (all files). If present in this file, bail with that error
        if res['unhandled']:
            code,f,line,col=res['unhandled']
            loc=Loc(f,line,col,'')
            err=Error('unhandledChar','error',f"The code contains unhandled character(s) (character code={code}). Neither unicode nor extended ascii is supported.",[loc],rank=rank_for('unhandledChar'),critical=True)
            self.errors.append(err); self.analyzer.critical_ids.add('unhandledChar'); self.critical=True
            raise BailoutTU()
        self.include_stack.append(real_abs)
        cond_stack=[]
        line_override=None # (file, next_line_number_for_next_raw_line, raw_line_of_directive) simple: dict raw_line->(file,line)
        line_map={} # raw lineno -> (disp, adjusted line)
        try:
            for rl in res['raw_lines']:
                if rl.is_directive:
                    # flush pending only for directives that affect expansion / inclusion / conditional boundaries. For any directive flush to be safe.
                    self.flush_pending()
                    self._handle_directive(rl, display, real, cond_stack, line_map, res)
                    continue
                # code line
                if cond_stack and not all(fr['active'] for fr in cond_stack):
                    continue
                toks=rl.tokens
                if rl.line in line_map:
                    f2,l2=line_map[rl.line]
                    newtoks=[]
                    for t in toks:
                        nt=Token(t.s,f2,l2,t.col,t.kind,t.str_value,t.char_value); nt.macro=t.macro; newtoks.append(nt)
                    toks=newtoks
                self.pending.extend(toks)
            # End of file: unmatched #if is not an error in cppcheck (observed)
        finally:
            self.include_stack.pop()
            self.flush_pending()
    def _current_active(self, stack):
        return all(fr['active'] for fr in stack) if stack else True
    def _handle_directive(self, rl, display, real, cond_stack, line_map, res):
        toks=rl.tokens
        if not toks or toks[0].s!='#':
            return
        self.directives.append(rl)
        if len(toks)<2:
            return
        name_tok=toks[1]
        name=name_tok.s
        parent_active=self._current_active(cond_stack)
        args=toks[2:]
        # Conditional handling first
        if name in ('if','ifdef','ifndef'):
            cond=False
            if parent_active:
                if name=='ifdef':
                    cond = bool(args and args[0].s in self.macros)
                elif name=='ifndef':
                    cond = bool(args and args[0].s not in self.macros) if args else False
                else:
                    v=evaluate_preprocessor_expr(args, self.macros, self.analyzer.settings, self.language)
                    cond = bool(v) if v is not None else False
            active=parent_active and cond
            cond_stack.append({'parent_active':parent_active,'active':active,'any_taken':active,'seen_else':False})
            return
        if name=='elif':
            if not cond_stack:
                self._syntax_directive_error(name_tok, "#elif without #if")
                raise BailoutTU()
            fr=cond_stack[-1]
            if fr['seen_else']:
                # ignore?
                fr['active']=False; return
            if fr['parent_active'] and not fr['any_taken']:
                v=evaluate_preprocessor_expr(args, self.macros, self.analyzer.settings, self.language)
                cond=bool(v) if v is not None else False
                fr['active']=cond; fr['any_taken']=cond
            else:
                fr['active']=False
            return
        if name=='else':
            if not cond_stack:
                self._syntax_directive_error(name_tok, "#else without #if"); raise BailoutTU()
            fr=cond_stack[-1]
            fr['active']=fr['parent_active'] and not fr['any_taken']
            fr['any_taken']=True; fr['seen_else']=True
            return
        if name=='endif':
            if not cond_stack:
                self._syntax_directive_error(name_tok, "#endif without #if"); raise BailoutTU()
            cond_stack.pop(); return
        # Non-conditional only if active
        if not parent_active:
            return
        if name=='define':
            if not args or args[0].kind!='id':
                self._syntax_directive_error(name_tok, "Failed to parse #define"); raise BailoutTU()
            mname=args[0].s
            # function-like if '(' immediately adjacent
            if len(args)>=2 and args[1].s=='(' and args[1].col==args[0].col+len(mname):
                # find closing )
                j=1; depth=0; params=[]; variadic=False; cur=[]
                while j < len(args):
                    t=args[j]
                    if t.s=='(': depth+=1; 
                    elif t.s==')':
                        depth-=1
                        if depth==0: break
                    else:
                        if depth==1:
                            if t.s=='...': variadic=True
                            elif t.kind=='id': params.append(t.s)
                    j+=1
                body=args[j+1:] if j < len(args) else []
                # __VA_ARGS__ marker if variadic unnamed - params doesn't include vararg name
                self.macros[mname]=Macro(mname,params,body,variadic)
            else:
                body=args[1:]
                self.macros[mname]=Macro(mname,None,body,False)
            return
        if name=='undef':
            if args: self.macros.pop(args[0].s,None)
            return
        if name=='include' or name=='include_next':
            if not args:
                self._syntax_directive_error(name_tok, "No header in #include"); raise BailoutTU()
            self._handle_include(rl,name_tok,args,display,real)
            return
        if name=='error':
            # text after error in original line: reconstruct after name token from rl.text? Use tokens rest join with spaces? Observed "#error Something bad" preserves original text after "error" with single spaces as in source. Use rl.text slice.
            text_after=_directive_text_after(rl, name_tok)
            loc=Loc(display,rl.line,name_tok.col,'')
            err=Error('preprocessorErrorDirective','error',f"#error {text_after}".rstrip(),[loc],rank=rank_for('preprocessorErrorDirective'),critical=True)
            self.errors.append(err); self.analyzer.critical_ids.add('preprocessorErrorDirective'); self.critical=True
            raise BailoutTU()
        if name=='pragma':
            if args and args[0].s=='once':
                self.pragma_once.add(os.path.realpath(real))
            return
        if name=='line':
            if args:
                try: num=int(parse_number_token(args[0]))
                except Exception: num=None
                fname=display
                if len(args)>=2 and args[1].kind=='string': fname=args[1].str_value or fname
                if num is not None:
                    # Map following raw lines: raw rl.line+1 -> num, etc. We'll populate lazily by storing mapping for subsequent lines as they come? Our loop needs line_map precomputed for future lines, but we are in loop - we can set a base in line_map dict with special key? Use a state stored in line_map as '__base__'
                    # We'll instead add entries for all remaining raw lines in file (we have res)
                    for other in res['raw_lines']:
                        if other.line>rl.line:
                            line_map[other.line]=(fname, num + (other.line-rl.line-1))
            return
        # warning / other directives ignored
        return
    def _syntax_directive_error(self,name_tok,msg):
        loc=Loc(name_tok.file,name_tok.line,name_tok.col,'')
        err=Error('syntaxError','error',msg,[loc],rank=rank_for('syntaxError'),critical=True)
        self.errors.append(err); self.analyzer.critical_ids.add('syntaxError'); self.critical=True
    def _handle_include(self, rl, name_tok, args, display, real):
        # Expand args macros first (for computed includes)
        exp=expand_tokens(args, self.macros)
        if not exp:
            return
        quote_type=None; inc_name=None
        if exp[0].kind=='string':
            quote_type='"'; inc_name=exp[0].str_value if exp[0].str_value is not None else exp[0].s.strip('"')
        elif exp[0].s=='<':
            quote_type='<'
            parts=[]
            for t in exp[1:]:
                if t.s=='>': break
                parts.append(t.s)
            inc_name=''.join(parts)
        else:
            # could be a string without kind? ignore
            return
        if inc_name is None: return
        candidates=[]
        if os.path.isabs(inc_name):
            candidates.append((inc_name, normalize_path(inc_name)))
        else:
            if quote_type=='"':
                # directory of current file real
                cur_real_dir=os.path.dirname(real)
                cur_disp_dir=posixpath.dirname(display)
                cand_real=os.path.join(cur_real_dir, inc_name) if cur_real_dir else inc_name
                cand_disp=normalize_path(posixpath.join(cur_disp_dir, inc_name)) if cur_disp_dir else normalize_path(inc_name)
                candidates.append((cand_real,cand_disp))
            # -I paths (entry extra includes first? project includes + cli combined order: project includes perhaps before CLI? We'll use entry extras then settings)
            inc_paths=list(self.entry.extra_includes or [])+list(self.analyzer.settings.includes)
            for ip in inc_paths:
                if ip=="": continue
                cand_real=os.path.join(ip, inc_name) if os.path.isabs(ip) else os.path.join(os.getcwd(), ip, inc_name)
                cand_disp=normalize_path(posixpath.join(ip.replace(os.sep,'/'), inc_name))
                candidates.append((cand_real,cand_disp))
        for cand_real,cand_disp in candidates:
            if os.path.isfile(cand_real):
                self.process_file(cand_disp, cand_real, is_include=True)
                return
        # not found
        if self.analyzer.settings.is_enabled('missingInclude'):
            loc=Loc(display, rl.line, name_tok.col, '')
            if quote_type=='"':
                err=Error('missingInclude','information',f'Include file: "{inc_name}" not found.',[loc],rank=-80)
            else:
                err=Error('missingIncludeSystem','information',f'Include file: <{inc_name}> not found. Please note: Standard library headers do not need to be provided to get proper results.',[loc],rank=-80)
            self.errors.append(err)

def _directive_text_after(rl, name_tok):
    # rl.text is original logical line. Find name token end by col
    # col is 1-index; name starts at name_tok.col, length len(name)
    # But BOM offset maybe not. Approx: search in text for name occurrence after #
    text=rl.text
    # find '#'
    idx=text.find('#')
    if idx>=0:
        rest=text[idx+1:].lstrip()
        # remove directive name word
        m=re.match(r'[A-Za-z_][A-Za-z0-9_]*\s*(.*)$', rest, re.S)
        if m: return m.group(1).strip()
    return ''

def preprocess_tu(analyzer, entry, language, config_items):
    state=_TUState(analyzer,entry,language,config_items)
    result=PreprocResult()
    try:
        state.process_entry()
    except BailoutTU:
        pass
    result.tokens=state.tokens; result.errors=state.errors; result.critical=state.critical; result.directives=state.directives
    return result

