        val=-1
        # token index global for entries: iterate over segments in global index range
        segs=split_top_range(toks,brace_idx+1,close,',')
        for (a,b) in segs:
            if a>=b: continue
            name_tok=None; name_idx=None
            eq=find_top_token(toks,a,b,'=')
            name_end=eq if eq is not None else b
            for k in range(a,name_end):
                if toks[k].kind=='id': name_tok=toks[k]; name_idx=k; break
            if name_tok is None: continue
            if eq is not None:
                v=eval_const_expr(toks[eq+1:b], var_values={n:{'known_value':vv} for n,vv in self.enums.items()}, sizeof_resolver=self._sizeof_resolver_global)
                if v is not None: val=int(v)
                else: val=val+1
            else:
                val+=1
            self.enums[name_tok.s]=val
    def _sizeof_resolver_global(self, inner, in_paren=False):
        return sizeof_of_tokens(self, inner, None)
    def _parse_class_header(self,start,brace_idx,kw_idx_rel,kw):
        toks=self.tokens; header=toks[start:brace_idx]; kw_pos=kw_idx_rel
        name=None; name_tok=None
        # name is first id after kw (skip template args?)
        for idx in range(kw_pos+1,len(header)):
            if header[idx].kind=='id':
                name=header[idx].s; name_tok=header[idx]; break
            if header[idx].s in (':','{'): break
        ci=ClassInfo(name or '', name_tok, kw)
