                    ci.bases.append((t.s,t))
        return ci
    def _try_function(self,start,brace_idx,context,class_info,access,body=None):
        toks=self.tokens
        # find '(' that starts param list: search from start to brace_idx, choose first '(' whose preceding token is identifier/~id/operator etc and whose matching ')' < brace_idx, and after ')' tokens until '{' or ':' for ctor init, or const/noexcept etc
        i=start
        while i<brace_idx:
            if toks[i].s=='(':
                close=self.match.get(i)
                if close is None or close>brace_idx: return None
                # name token before '('
                if i==start: return None
                name_idx=i-1; name_tok=toks[name_idx]
                # handle operator forms: "operator" then symbol before '(' - name should be "operatorX"
                fname=None
                is_ctor=False; is_dtor=False
                qualified_class=None
                if name_tok.kind=='id':
                    fname=name_tok.s
                    if name_idx>=start+1 and toks[name_idx-1].s=='~':
                        is_dtor=True; fname='~'+fname
                    # qualified Class::func
                    if name_idx>=start+2 and toks[name_idx-1].s=='::' and toks[name_idx-2].kind=='id':
                        qualified_class=toks[name_idx-2].s
                    if name_idx>=start+1 and toks[name_idx-1].s=='operator':
                        fname='operator'
                elif name_tok.s in ('+','-','*','/','=','==','[]','()'):
                    fname='operator'+name_tok.s
                elif name_tok.s in (']',')'):
                    # operator[] / operator() name token is closing
                    fname='operator'
                    name_tok=toks[i-2] if i>=2 else name_tok
                else:
                    return None
                # tokens between close+1 and brace should only be qualifiers / ctor init ':' list / noexcept / const / override / =delete etc.
                ok=True
                k=close+1
                # Allow ':' for ctor initializers: skip until '{' at brace_idx (already) - any tokens allowed until brace (ctor init calls have parens)
                # If no ':' then only allowed words:
                has_colon = any(toks[x].s==':' for x in range(close+1,brace_idx))
                if not has_colon:
                    allowed={'const','noexcept','override','final','volatile','&','&&','throw','(' ,')','mutable'}
                    # noexcept(expr) etc - we allow parens groups as a whole check skipping match
                    kk=close+1
                    while kk<brace_idx:
                        if toks[kk].s=='(':
                            m=self.match.get(kk); 
                            if m is None: ok=False; break
                            kk=m+1; continue
                        if toks[kk].s not in allowed:
