                            if toks[kk].s=='->':
                                break
                            ok=False; break
                        kk+=1
                if not ok: return None
                func=FuncInfo(fname,name_tok); func.name_idx=name_idx; func.header_start=start; func.param_range=(i+1,close)
                func.is_definition=True; func.body_start,func.body_end=body
                func.class_name=qualified_class or (class_info.name if class_info else None)
                func.is_method=class_info is not None or qualified_class is not None
                func.access=access
                # return type tokens: start .. name start (excluding qualified class)
                ret_end=name_idx
                if qualified_class: ret_end=name_idx-2
                if is_dtor: ret_end=name_idx-1
                func.ret_toks=toks[start:ret_end] if ret_end>start else []
                words=[t.s for t in func.ret_toks]
                func.is_static='static' in words
                func.is_virtual='virtual' in words
                # constructor: no return type and name == class name (or qualified)
                if (class_info and fname==class_info.name) or (qualified_class and fname==qualified_class): func.is_constructor=True
                if is_dtor: func.is_destructor=True
                func.params=self._parse_params(i+1,close)
                return func
            i+=1
        return None
    def _parse_params(self,start,end):
        toks=self.tokens; params=[]
        if start>=end: return params
        if start+1==end and toks[start].s=='void': return params
        segs=split_top_range(toks,start,end,',')
        for (a,b) in segs:
            if a>=b: continue
            if toks[a].s=='...' and a+1==b: continue
            eq=find_top_token(toks,a,b,'=')
            decl_end=eq if eq is not None else b
            var=self._parse_single_declarator(a,decl_end,context='param')
            if var is not None:
                var.is_param=True
                if eq is not None: var.init_toks=toks[eq+1:b]; var.init_range=(eq+1,b)
                params.append(var)
            else:
                # unnamed param create placeholder with empty name
                var=VarInfo('',toks[a]); var.is_param=True; var.type_toks=toks[a:decl_end]; params.append(var)
        return params
    def _process_declaration_with_brace_init(self,start,brace_idx,close,semi,context,class_info,access):
        # Treat header before brace as declarator, init tokens are brace range
        vars_=self._parse_var_declarators(start,brace_idx, type_toks=None, context=context, class_info=class_info, access=access, brace_init=(brace_idx,close))
    def _process_declaration(self,start,end,context,class_info,access):
        toks=self.tokens
        if start>=end: return
        words=[t.s for t in toks[start:end]]
        # typedef
        if words and words[0]=='typedef':
            # last identifier is alias (except function pointer)
            # find alias: if '(' with (*alias) pattern, alias inside.
            alias=None
            for idx in range(start,end):
                if toks[idx].s=='(' and idx+2<end and toks[idx+1].s=='*' and toks[idx+2].kind=='id':
                    alias=toks[idx+2].s; break
            if alias is None:
                for idx in range(end-1,start,-1):
                    if toks[idx].kind=='id': alias=toks[idx].s; break
            if alias:
                self.typedefs[alias]=toks[start:end]
            # typedef struct {...} Name already handled at brace level? This ; case no brace
            return
        if words and words[0]=='using' and '=' in words:
            # using Alias = Type;
            for idx in range(start,end):
                if toks[idx].kind=='id' and toks[idx].s!='using': self.typedefs[toks[idx].s]=toks[start:end]; break
            return
        # static_assert etc ignore
        if words and words[0] in ('static_assert','_Static_assert'): return
        # Function prototype attempt: find '('
        # Only if no '=' before '(' and pattern looks like params.
        paren_idx=None
        for idx in range(start,end):
            if toks[idx].s=='(':
                paren_idx=idx; break
            if toks[idx].s=='=': break
        if paren_idx is not None:
            func=self._try_function_prototype(start,end,paren_idx,context,class_info,access)
            if func is not None:
                self.functions.append(func)
                if class_info is not None: class_info.methods.append(func)
                return
        # else variables
        self._parse_var_declarators(start,end,type_toks=None,context=context,class_info=class_info,access=access)
    def _try_function_prototype(self,start,end,paren_idx,context,class_info,access):
        toks=self.tokens
        close=self.match.get(paren_idx)
        if close is None or close>end: return None
        if paren_idx==start: return None
        name_idx=paren_idx-1; name_tok=toks[name_idx]
        if name_tok.kind!='id' and name_tok.s not in (']',')'): return None
        # Distinguish variable init int x(5); params inside if they look like expression values (single num / string / id alone) and name's preceding tokens are a type - then variable not function.
        inner=toks[paren_idx+1:close]
        # If context is file/class and inner are types: plausible params include type keywords/ * & :: or empty or void or comma separated with at least 2 tokens per param etc.
        def is_param_like():
            if not inner: return True
            if len(inner)==1 and inner[0].s=='void': return True
            segs=split_top_range(toks,paren_idx+1,close,',')
            for (a,b) in segs:
                seg=toks[a:b]
                if not seg: continue
                if len(seg)==1 and seg[0].kind in ('num','string','char'): return False
                # single identifier could be a type (unnamed param) OR var value. If declaration like int x(y); y is identifier variable initialiser - ambiguous. In C, int x(y); at file scope is function declaration x with param y type? Actually int x(y); could be function decl with unnamed param of type y if y is type, else variable. cppcheck likely treats as function if y is known type? We'll treat single id segment as param-like if it's known type/typedef/class or starts uppercase? else var init False.
                if len(seg)==1 and seg[0].kind=='id':
                    if seg[0].s in TYPE_KEYWORDS or seg[0].s in self.typedefs or seg[0].s in [c.name for c in self.classes]: continue
                    else: return False
            return True
        if not is_param_like():
            return None
        # After close, allowed tokens: const/noexcept/override/ =0/=delete/=default/; etc
        suffix=[t.s for t in toks[close+1:end]]
        if any(s not in ('const','noexcept','override','final','volatile','&','&&','=','0','delete','default','pure','virtual') and not s[0].isalpha() for s in suffix):
            pass
        fname=name_tok.s if name_tok.kind=='id' else 'operator'
        qualified=None; is_dtor=False
        if name_idx>=start+2 and toks[name_idx-1].s=='::' and toks[name_idx-2].kind=='id': qualified=toks[name_idx-2].s
        if name_idx>=start+1 and toks[name_idx-1].s=='~': is_dtor=True; fname='~'+fname
        func=FuncInfo(fname,name_tok); func.name_idx=name_idx; func.header_start=start; func.param_range=(paren_idx+1,close); func.is_definition=False
        func.class_name=qualified or (class_info.name if class_info else None); func.is_method=class_info is not None or qualified is not None; func.access=access
        ret_end=name_idx-2 if qualified else (name_idx-1 if is_dtor else name_idx)
        func.ret_toks=toks[start:ret_end] if ret_end>start else []
        words=[t.s for t in func.ret_toks]; func.is_static='static' in words; func.is_virtual='virtual' in words
        if (class_info and fname==class_info.name) or (qualified and fname==qualified): func.is_constructor=True
        if is_dtor: func.is_destructor=True
        func.params=self._parse_params(paren_idx+1,close)
        return func
    def _parse_var_declarators(self,start,end,type_toks,context,class_info,access,brace_init=None):
        toks=self.tokens
        if start>=end and brace_init is None: return []
        # Split declarators by commas, but base type is common. Need determine base type end: It's in first declarator only; other declarators have no type.
        segs=split_top_range(toks,start,end,',') if brace_init is None else [(start,end)]
        result=[]; common_type=None; common_flags={}
        for seg_index,(a,b) in enumerate(segs):
            if a>=b: continue
            eq=find_top_token(toks,a,b,'=')
            decl_end=eq if eq is not None else b
            var=None
            if seg_index==0 and type_toks is None:
                var=self._parse_single_declarator(a,decl_end,context=context)
                if var is not None:
                    common_type=var.type_toks; common_flags={'is_static':var.is_static,'is_const':var.is_const}
            else:
                # declarator without type: construct using common_type
                var=self._parse_declarator_only(a,decl_end, common_type or type_toks or [])
                if var is not None:
                    var.is_static=common_flags.get('is_static',False); var.is_const=common_flags.get('is_const',False)
                    # recompute base etc based on type
                    _fill_type_info(var, var.type_toks)
            if var is None: continue
            # Bitfield member: name : width - name before ':' - _parse_single may include colon tokens in type etc. Accept.
            if eq is not None:
                var.init_toks=toks[eq+1:b]; var.init_range=(eq+1,b)
            if brace_init is not None:
                var.init_toks=toks[brace_init[0]:brace_init[1]+1]; var.init_range=brace_init
            var.is_global=(context=='file')
            var.is_member=(context=='class')
            if class_info is not None:
                var.class_name=class_info.name; class_info.members.append(var)
            elif context=='file':
                self.globals.append(var)
            result.append(var)
        return result
    def _parse_single_declarator(self,start,end,context='var'):
        toks=self.tokens
        # Returns VarInfo or None if no declarator name
        # Skip attributes [[...]] etc: skip leading [ [ ] ] groups
        i=start
        is_static=False; is_const=False
        # Find array brackets segments after name later. To identify name: find candidate identifier token that is declarator name.
        # Approach: Find first '=' (already excluded by end often), the name is identifier before first '[' or ':' (bitfield) or '(' (func pointer/init), or last identifier in sequence excluding type tokens.
        # First handle function pointer: '(' '*' name ')'
        for idx in range(start,end-2):
            if toks[idx].s=='(' and toks[idx+1].s=='*' and toks[idx+2].kind=='id':
                var=VarInfo(toks[idx+2].s,toks[idx+2]); var.name_idx=idx+2; var.pointer_level=1; var.type_toks=toks[start:idx]; var.decl_idx=start
                _fill_type_info(var,var.type_toks)
                return var
        # Gather tokens, skip leading qualifiers/storage words while building type token list
        type_end=None; name_idx=None
        # Determine array bracket start
        brack_idx=None
        for idx in range(start,end):
            if toks[idx].s=='[': brack_idx=idx; break
            if toks[idx].s=='=': break
        search_end=brack_idx if brack_idx is not None else end
        # Handle '(' for direct init: name before '('
        paren_idx=None
        for idx in range(start,search_end):
            if toks[idx].s=='(':
                paren_idx=idx; break
        if paren_idx is not None:
            search_end=paren_idx
        # Bitfield ':'
        colon_idx=None
        for idx in range(start,search_end):
            if toks[idx].s==':' and not (idx+1<search_end and toks[idx+1].s==':') and not (idx>start and toks[idx-1].s==':'):
                colon_idx=idx; break
        if colon_idx is not None:
            search_end=colon_idx
        # Name is last identifier in [start,search_end) that is not a type keyword, not part of qualified type (followed by :: or preceded by :: with more following?) But type may be class name e.g. "MyClass var" -> last id var. "unsigned int var" last.
        candidates=[]
        for idx in range(start,search_end):
            t=toks[idx]
            if t.kind!='id': continue
            if t.s in TYPE_KEYWORDS or t.s in QUALIFIERS: continue
            # if token is a known struct/class/enum keyword handled above
            if idx>start and toks[idx-1].s in ('struct','class','enum','union'):
                # this is type name, but could also be var if it's the only candidate and type is struct anonymous? Keep as type candidate not name unless there is no other candidate and pattern weird.
                continue
            # if followed by :: -> part of qualified type, not name (except if it's the last and following :: leads to nested type name only - then no var name)
            if idx+1<search_end and toks[idx+1].s=='::':
                continue
            # if preceded by :: and it's last token and there are at least 2 ids, it could be either nested type (no var) or var with qualified type should have another id after. If this is the only candidate after :: chain, treat as type not name.
            if idx>start and toks[idx-1].s=='::':
                # If there will be another candidate later, this is type; if it's final candidate, mark special - we can decide later based count.
                candidates.append((idx,True))
            else:
                candidates.append((idx,False))
        if not candidates:
            return None
        # If only one candidate and it is qualified (preceded ::) - it's a type only, no name
        if len(candidates)==1 and candidates[0][1]:
            return None
        # If only one candidate and its index == start or preceded only by qualifiers - then it's type only (unnamed param)
        idx_only, _ = candidates[-1]
        # Check if there is only one non-qualifier identifier in total and no '*' '&' before it - that is a type in param context or maybe variable with unknown type missing. In local/global variable declaration context, a miss would be e.g. "x;" statement - that's not a declaration. Return None for single id alone.
        nonqual_tokens=[t for t in toks[start:search_end] if t.s not in QUALIFIERS]
        if len(candidates)==1 and len(nonqual_tokens)==1:
            return None
        name_idx=candidates[-1][0]
        # Valid check: tokens before name should form a type: at least one type token / * & etc before name. If name is first token and there are other ids after... not possible candidates last.
        if name_idx==start:
            return None
        var=VarInfo(toks[name_idx].s,toks[name_idx]); var.name_idx=name_idx; var.decl_idx=start
        # type tokens are everything before name excluding trailing * & pointer/ref tokens (count them)
        ptr=0; is_ref=False; type_toks=[]
        for t in toks[start:name_idx]:
            if t.s=='*': ptr+=1
            elif t.s=='&' or t.s=='&&': is_ref=True
            else: type_toks.append(t)
        var.pointer_level=ptr; var.is_ref=is_ref; var.type_toks=type_toks
        # '*' after name? not in C declarator syntax except... ignore
        # array sizes after name
        if brack_idx is not None and brack_idx>name_idx:
            var.is_array=True; sizes=[]
            idx=brack_idx
            while idx<end and toks[idx].s=='[':
                m=self.match.get(idx)
                if m is None: break
                sz_toks=toks[idx+1:m]
                if not sz_toks: sizes.append(None)
                else:
                    v=eval_const_expr(sz_toks, var_values=self._global_const_values(), sizeof_resolver=self._sizeof_resolver_global)
                    sizes.append(int(v) if isinstance(v,(int,float)) else None)
                idx=m+1
                if idx<end and toks[idx].s!='[': break
            var.array_sizes=sizes
        _fill_type_info(var,type_toks)
        # is_static/const from type tokens/full start tokens
        allwords=[t.s for t in toks[start:name_idx]]
        var.is_static='static' in allwords; var.is_const='const' in allwords
        # direct init parens
        if paren_idx is not None and paren_idx==name_idx+1:
            m=self.match.get(paren_idx)
            if m is not None:
                var.init_toks=toks[paren_idx+1:m]; var.init_range=(paren_idx+1,m)
        return var
    def _parse_declarator_only(self,start,end,type_toks):
        toks=self.tokens
        # tokens are like *name, name[10], &name etc without base type
        name_idx=None
        for idx in range(start,end):
            if toks[idx].kind=='id': name_idx=idx; break
            if toks[idx].s=='[': break
        if name_idx is None: return None
        var=VarInfo(toks[name_idx].s,toks[name_idx]); var.name_idx=name_idx; var.decl_idx=start; var.type_toks=list(type_toks or [])
        ptr=sum(1 for t in toks[start:name_idx] if t.s=='*'); var.pointer_level=ptr; var.is_ref=any(t.s in ('&','&&') for t in toks[start:name_idx])
        # array after
        idx=name_idx+1; sizes=[]
        while idx<end and toks[idx].s=='[':
            var.is_array=True; m=self.match.get(idx)
            if m is None: break
            sz=toks[idx+1:m]; v=eval_const_expr(sz,var_values=self._global_const_values(),sizeof_resolver=self._sizeof_resolver_global) if sz else None
            sizes.append(int(v) if isinstance(v,(int,float)) else None); idx=m+1
        var.array_sizes=sizes
        return var
    def _global_const_values(self):
        d={}
        for n,v in self.enums.items(): d[n]={'known_value':v}
        # const globals with literal init evaluated later may not be filled during parse order - also include already parsed globals
        for g in self.globals:
            if g.is_const and g.init_toks:
                v=eval_const_expr(g.init_toks, var_values=d, sizeof_resolver=self._sizeof_resolver_global)
                if v is not None: d[g.name]={'known_value':v}
        return d

def _fill_type_info(var, type_toks):
    words=[t.s for t in type_toks]
    var.base_type=' '.join(words)
    clean=[w for w in words if w not in ('const','volatile','static','extern','register','mutable','signed','unsigned','struct','class','enum','union')]
    var.elem_type=' '.join(clean) if clean else var.base_type
    var.is_unsigned='unsigned' in words
    var.is_bool='bool' in words or '_Bool' in words
    var.is_float=any(w in ('float','double') for w in words)
    # type name for size: use clean join or original
    var.type_name_for_size=var.elem_type

def sizeof_of_tokens(tu, inner, func_context=None):
    # inner tokens are either a type or an expression/variable/array
    settings=tu.analyzer.settings
    # Strip *
    if not inner: return None
    # If it's a single variable identifier known in context, resolver in func context may handle outside. This global resolver: look up global/class member?
    # If inner looks like a type:
    text=' '.join(t.s for t in inner)
    # pointer type: ends with *
    if inner[-1].s=='*':
        return settings.sizes.get('pointer',64)//8
