    int_map={'int8_t':1,'uint8_t':1,'int16_t':2,'uint16_t':2,'int32_t':4,'uint32_t':4,'int64_t':8,'uint64_t':8,'intptr_t':8,'uintptr_t':8,'ptrdiff_t':8}
    if type_clean in int_map:
        # pointer sized types depend platform: approximate pointer//8 for ptr types
        if 'ptr' in type_clean: return sizes.get('pointer',64)//8
        return int_map[type_clean]
    # If it's a variable/array expression handled by caller (func resolver returns) else None
    return None

