        elif s=='[': depthb+=1
        elif s==']': depthb-=1
        elif s=='{': depthbr+=1
        elif s=='}':
            if depthbr==0:
                return i
            depthbr-=1
            # if a brace block closes and next is ';' it's included by continuing to ; ; if next is else etc expression statement might be class decl etc. For local struct decl, semi follows.
