def default_var_state(var, tu, is_global=False):
    st={'init':'init' if (is_global or var.is_static or var.is_param) else ('init' if var.init_range is not None or var.init_toks else 'uninit'),
    'known':None,'known_tok':None,'known_text':None,
    'ptr':'unknown','alloc_id':None,'alloc_kind':None,'alloc_group':None,'freed':False,'escaped':False,'data_init':None,'alloc_tok':None,'alloc_size':None,'leak_reported':False,
    'string_len':None,'string_tok':None,'local_addr':None,'local_addr_tok':None,'member_init':{},'reported_uninit':False,'reported_uninit_member':set(),'close_tok':None,'free_tok':None,'deref_reported_alloc':None}
    if var.is_param:
        st['init']='init'
    # Non-primitive class objects default initialized
    type_words=[t.s for t in var.type_toks]
    primitive=any(w in TYPE_KEYWORDS and w!='auto' for w in type_words) or var.pointer_level>0 or var.is_array and not type_words
    # struct types: if type starts struct/union or type name is a known struct class, members uninit -> keep uninit for member checks but object scalar init state...
    if not primitive and var.pointer_level==0 and not var.is_array:
        # unknown/class type: assume initialized by ctor unless it's a known POD struct defined in TU
        type_name=var.elem_type.split()[-1] if var.elem_type else ''
        known_class=next((c for c in tu.classes if c.name==type_name),None) if tu else None
        has_ctor=False
        if known_class:
            has_ctor=any(m.is_constructor for m in known_class.methods)
        if known_class is None or has_ctor:
            st['init']='init'
    return st

def clone_env(env):
    out={}
    for k,v in env.items():
        nv=dict(v)
        if isinstance(v.get('member_init'),dict): nv['member_init']=dict(v['member_init'])
        if isinstance(v.get('reported_uninit_member'),set): nv['reported_uninit_member']=set(v['reported_uninit_member'])
        out[k]=nv
    return out

def merge_envs(envs):
    if not envs: return {}
    if len(envs)==1: return envs[0]
    keys=set()
    for e in envs: keys.update(e.keys())
    out={}
    for k in keys:
        states=[e.get(k) for e in envs if k in e]
        if len(states)==1:
            # var only existed in a branch (declared there) - outside branch it's scoped, dropping is handled by scope end; but if a var declared before branch it exists in all envs. Keep single state only if it's from... To be safe keep copy.
            st=dict(states[0]); 
            if isinstance(st.get('member_init'),dict): st['member_init']=dict(st['member_init'])
            out[k]=st; continue
        base=dict(states[0])
        if isinstance(base.get('member_init'),dict): base['member_init']=dict(base['member_init'])
        # init
        inits={s.get('init') for s in states}
        base['init']=inits.pop() if len(inits)==1 else 'maybe'
        # known
        knowns={s.get('known') for s in states}
        if len(knowns)!=1:
            base['known']=None; base['known_tok']=None; base['known_text']=None
        # string_len / ptr / freed / alloc
        for field in ('ptr','alloc_id','alloc_kind','alloc_group','string_len','alloc_size','local_addr'):
            vals={s.get(field) if not isinstance(s.get(field),VarInfo) else id(s.get(field)) for s in states}
            if len(vals)!=1:
                if field=='ptr': base[field]='unknown'
                elif field=='local_addr': base[field]=base.get(field)  # keep first? if different could false - set None
                # for local_addr differing set None
                if field=='local_addr': base[field]=None
                elif field!='ptr': base[field]=None if field not in ('alloc_id',) else base.get(field)
                # alloc_id keep if same? len !=1 means different alloc ids from branches - allocation could be either, keep first as representative but freed state merged below.
                if field=='alloc_id': base[field]=states[0].get(field)
        base['freed']=all(s.get('freed') for s in states)
        base['escaped']=any(s.get('escaped') for s in states)
        if any(s.get('freed') for s in states) and not base['freed']:
            base['maybe_freed']=True
        base['reported_uninit']=any(s.get('reported_uninit') for s in states)
        # member_init merge
        mall={}
        for s in states:
            for mk,mv in (s.get('member_init') or {}).items():
                mall.setdefault(mk,set()).add(mv)
        base['member_init']={mk:(list(v)[0] if len(v)==1 else 'maybe') for mk,v in mall.items()}
        out[k]=base
    return out

class FuncAnalyzer:
    def __init__(self,tu,func,tu_errors,analyzer):
        self.tu=tu; self.func=func; self.errors=tu_errors; self.analyzer=analyzer; self.settings=analyzer.settings; self.lib=analyzer.lib
        self.ctx=FuncContext(tu,func)
        self.locals_by_id={id(v):v for v in self.ctx.locals}
        # Add globals not in locals for env resolution (token_var may include globals)
        self.seq=0
        self.next_alloc_id=1
        self.assignment_events=[] # dict var, eq_tok idx, kind, display name, rhs range, is_decl_init
        self.read_events=[] # (var, idx, kind)
        self.call_events=[]
        self.token_index_by_id={id(t):i for i,t in enumerate(tu.tokens)}
        self.stmts=parse_block_stmts(tu,func.body_start,func.body_end) if func.body_start is not None else []
    # ---------- utilities ----------
    def add_error(self, err, require=None):
        if require:
            eg=self.settings.enabled_groups()
            if not any(r in eg for r in require):
                return False
        err.rank=rank_for(err.id) if err.rank==0 else err.rank
        err.seq=self.seq; self.seq+=1
        # local dedup identical
        key=err.dedup_key()
        for e in self.errors:
            if e.dedup_key()==key: return False
        self.errors.append(err); return True
    def state_for(self, env, var):
        key=id(var)
        if key not in env:
            env[key]=default_var_state(var,self.tu,is_global=var.is_global)
        return env[key]
    def ensure_global_states(self, env):
        for g in self.tu.globals:
            st=self.state_for(env,g)
            if st.get('_global_init_done'): continue
            st['_global_init_done']=True
            if g.init_range:
                st['init']='init'
                # evaluate known with enums etc (no env for other globals except const map)
                v=eval_const_expr(self.tu.tokens[g.init_range[0]:g.init_range[1]], var_values=self.tu._global_const_values(), sizeof_resolver=lambda inner,par=False: self.sizeof_resolver(inner,env))
                if v is not None:
                    st['known']=v
                    if g.init_range[0]<g.init_range[1]: st['known_tok']=self.tu.tokens[g.init_range[0]]; st['known_text']=f"{g.name}={tokens_text(self.tu.tokens[g.init_range[0]:g.init_range[1]])}"
                # string literal
                if g.init_toks and len(g.init_toks)==1 and g.init_toks[0].kind=='string':
                    st['string_len']=len(g.init_toks[0].str_value or '')+1; st['string_tok']=g.init_toks[0]
                    if g.is_array and (not g.array_sizes or g.array_sizes[0] is None):
                        g.array_sizes=[st['string_len']]
            else:
                st['init']='init'; 
                if not g.is_array and g.pointer_level==0 and not (set([t.s for t in g.type_toks]) & {'struct','class'}):
                    # zero initialized scalars - but cppcheck valueflow may know global int =0? For global int x; int f(){return 1/x;} would it flag? Probably yes for static/global zero. Set known 0 for numeric globals.
                    if any(t.s in TYPE_KEYWORDS for t in g.type_toks): st['known']=0
    def sizeof_resolver(self, inner, env=None):
        toks=self.tu.tokens
        if not inner: return None
        # Type* ?
        if inner[-1].s=='*':
            return self.settings.sizes.get('pointer',64)//8
        # variable/expression first token resolution
        # find first id token in inner that resolves to var based on token identity
        for t in inner:
            idx=self.token_index_by_id.get(id(t))
            if idx is not None and idx in self.ctx.token_var:
                var=self.ctx.token_var[idx]
                return self.sizeof_var(var, env)
            if t.kind=='string':
                return len(t.str_value or '')+1
            if t.kind=='char':
                return 1
            break
        # type name
        r=sizeof_of_tokens(self.tu,inner)
        if r is not None: return r
        # typedef / class names: sum members if class known
        names=[t.s for t in inner if t.kind=='id']
        if names:
            ci=next((c for c in self.tu.classes if c.name==names[-1]),None)
            if ci:
                total=0
                for m in ci.members:
                    sz=self.sizeof_var(m,env)
                    if sz is None: return None
                    total+=sz
                return total
        return None
    def elem_size(self,var):
        # size in bytes of element / scalar type
        settings=self.settings
        if var.pointer_level>0 and not var.is_array:
            return settings.sizes.get('pointer',64)//8
        # For array var, elem is base type
        # build from type_toks
        inner=var.type_toks
        r=sizeof_of_tokens(self.tu,inner)
        if r is not None: return r
        # struct/class type member size sum
        names=[t.s for t in inner if t.kind=='id']
        if names:
            ci=next((c for c in self.tu.classes if c.name==names[-1]),None)
            if ci:
                total=0
                for m in ci.members:
                    sz=self.sizeof_var(m)
                    if sz is None: return None
                    total+=sz
                return total
            if names[-1] in ('string',): return 32
        # unknown type assume 4? Returning None is safer for computations except int arrays with typedefs: default 4 if type looks integer-ish?
        return None
    def sizeof_var(self,var_env_state=None, env=None):
        if var.is_array:
            # parameter arrays decay to pointer
            if var.is_param:
                return self.settings.sizes.get('pointer',64)//8
            es=self.elem_size(var)
            if es is None: return None
            prod=es; 
            # array_sizes may have None for unsized string array: get string len from state if env given?
            for sz in var.array_sizes:
                if sz is None:
                    # try init string
                    if var.init_toks and len(var.init_toks)==1 and var.init_toks[0].kind=='string':
                        prod*=len(var.init_toks[0].str_value or '')+1
                    else: return None
                else: prod*=sz
            return prod
        if var.pointer_level>0:
            return self.settings.sizes.get('pointer',64)//8
        return self.elem_size(var)
    def token_value_map(self,a,b,env):
        mp={}
        for idx in range(a,b):
            t=self.tu.tokens[idx]
            if idx in self.ctx.token_var:
                var=self.ctx.token_var[idx]; st=env.get(id(var))
                if st and st.get('known') is not None: mp[id(t)]=st['known']
            elif t.kind=='id' and t.s in self.tu.enums:
                mp[id(t)]=self.tu.enums[t.s]
        return mp
    def eval_range(self,a,b,env):
        if a is None or b is None or a>=b: return None
        toks=self.tu.tokens[a:b]
        return eval_const_expr(toks, var_values=self.tu._global_const_values(), sizeof_resolver=lambda inner,par=False: self._sizeof_from_tokens(inner,env), token_value_map=self.token_value_map(a,b,env), language=self.tu.language)
    def _sizeof_from_tokens(self,inner,env):
        return self.sizeof_resolver(inner,env)
    def array_size_for_var(self,var,env):
        # returns (display_name_with_sizes, sizes list) or (None,None). For string pointer/array unsized from init.
        sizes=list(var.array_sizes) if var.array_sizes else []
        st=env.get(id(var)) if env else None
        if var.is_array:
            if sizes and sizes[0] is None:
                if st and st.get('string_len'): sizes[0]=st['string_len']
                elif var.init_toks and len(var.init_toks)==1 and var.init_toks[0].kind=='string': sizes[0]=len(var.init_toks[0].str_value or '')+1
            if sizes and all(s is not None for s in sizes):
                return sizes
            return sizes if sizes and sizes[0] is not None else None
        # char* pointing to string literal
        if st and st.get('string_len'):
            return [st['string_len']]
        return None
    # ---------- main ----------
    def analyze(self):
        if self.func.body_start is None: return
        env={}
        self.ensure_global_states(env)
        # initialize params / locals states lazily via state_for when needed, but initialize params now
        for p in self.func.params:
            if p.name: self.state_for(env,p)
        # missing return check added here? Order sorting will place rank60. Compute after exec? doesn't matter.
        self.check_missing_return()
        # execute statements
        self.exec_block(self.stmts, env, is_function_body=True)
        # separate passes that use events / tokens
        self.pass_unused_vars()
        self.pass_duplicate_and_syntactic()
        self.check_useless_assign_params()
    def check_missing_return(self):
        f=self.func
        if f.is_constructor or f.is_destructor: return
        ret_words=[t.s for t in f.ret_toks if t.s not in ('static','inline','virtual','explicit','friend','constexpr','extern')]
        if ret_words==['void']: return
        if f.name=='main': return
        # If no return type and name is class name already ctor handled. If ret empty and is method -> ctor/dtor.
        if not ret_words and f.is_method: return
        # If function is declared to return void via typedef? skip unknown
        if not block_fallthrough(self.tu,self.stmts,self.analyzer):
            return
        # location closing brace
        tok=self.tu.tokens[f.body_end]
        self.add_error(Error('missingReturn','error',"Found an exit path from function with non-void return type that has missing return statement",[Loc(tok.file,tok.line,tok.col,'')]))
    # ---------- statement execution ----------
    def exec_block(self,stmts,env,is_function_body=False):
        # returns (env_after, fallthrough) ; executes all stmts for checks even if dead after exit.
        dead=False; dead_env=None; dead_cause=None; unreachable_reported=False
        prev_if=None
        for st in stmts:
            cur_env=dead_env if dead else env
            if dead and not unreachable_reported and st.kind not in ('empty','case','label'):
                # unreachable code if previous cause is return/break/continue/goto/throw/noreturn
                if dead_cause in ('return','break','continue','throw','goto','noreturn'):
                    tok=self.tu.tokens[st.start]
                    if dead_cause=='return': msg="Statements following 'return' will never be executed."
                    elif dead_cause=='break': msg="Statements following 'break' will never be executed."
                    elif dead_cause=='continue': msg="Statements following 'continue' will never be executed."
                    else: msg="Code after a 'return' will never be executed." if False else f"Statements following '{dead_cause}' will never be executed."
                    self.add_error(Error('unreachableCode','style',msg,[Loc(tok.file,tok.line,tok.col,'')]),require=['style'])
                    unreachable_reported=True
            # duplicate condition tracking at block level
            if st.kind=='if' and prev_if is not None:
                self.check_duplicate_if(prev_if,st,cur_env)
            # exec
            fall=self.exec_stmt(st,cur_env)
            if st.kind=='if': prev_if=st
            elif st.kind not in ('empty',): 
                # if statement modifies anything? For simplicity if non-if statement executed, it could modify vars in prev if condition. Our duplicate check inside check_duplicate_if will scan assignments between start of previous condition and this one. Keep prev_if until next if regardless intervening statements? Cppcheck duplicateCondition only when conditions are in same scope and no side effects in between - checker scans between. Keep prev_if.
                pass
            if not fall and not dead:
                dead=True; dead_cause=st.kind if st.kind in ('return','break','continue','goto','throw') else 'noreturn'
                # After block exit, env remains as cur_env at exit point (already in env object if cur_env is env). Clone a dead env to continue checking unreachable statements without polluting env.
                dead_env=clone_env(cur_env)
            # If statement was a block/if etc, fall computed by exec_stmt returning fall.
        # scope exit leak / lifetime for variables declared inside this block: if this exec_block corresponds to a lexical block we need to know its variables. Instead function-level exec_stmt for 'block' will handle after calling exec_block.
        return (env, not dead)
    def exec_stmt(self,st,env):
        toks=self.tu.tokens
        if st.kind=='block':
            sub_env=env
            after,fall=self.exec_block(st.stmts,sub_env)
            # scope exit: locals declared in this block (scope_end == st.end (close+1)) become invalid/leak check
            close_tok=toks[st.end-1] if st.end-1 < len(toks) else toks[st.start]
            self.on_scope_exit(env, close_tok, scope_end=st.end)
            return fall
        if st.kind=='empty': return True
        if st.kind=='expr':
            a,b=st.expr
            self.exec_expr(a,b,env, top_statement=True)
            return stmt_fallthrough(self.tu,st,self.analyzer)
        if st.kind=='return':
            a,b=st.expr
            if a<b:
                self.check_return_expr(a,b,env,toks[st.start])
                self.exec_expr(a,b,env)
            self.on_return(st,env)
            return False
        if st.kind in ('break','continue','goto'):
            return False
        if st.kind=='throw':
            if st.expr: self.exec_expr(st.expr[0],st.expr[1],env)
            return False
        if st.kind=='label': return True
        if st.kind=='case':
            if st.expr: self.exec_expr(st.expr[0],st.expr[1],env)
            return True
        if st.kind=='if':
            return self.exec_if(st,env)
        if st.kind in ('while','do','for','switch'):
            return self.exec_loop(st,env)
        if st.kind=='try':
            if st.body: return self.exec_stmt(st.body,env)
            return True
        return True
    def exec_if(self,st,env):
        toks=self.tu.tokens
        cond_val=None
        if st.cond:
            # C++ if with initializer (int x=...; cond) - exec whole as expr for assignments
            self.exec_expr(st.cond[0],st.cond[1],env)
            cond_val=self.eval_range(st.cond[0],st.cond[1],env)
        # branch envs with constraints
        then_env=clone_env(env); else_env=clone_env(env)
        self.apply_condition_constraints(st.cond, then_env, truth=True)
        self.apply_condition_constraints(st.cond, else_env, truth=False)
        then_fall=True; else_fall=True
        if st.then:
            then_fall=self.exec_stmt(st.then, then_env)
        if st.els:
            else_fall=self.exec_stmt(st.els, else_env)
        # merge into env (mutate env dict contents)
        result=None
        if cond_val:
            result=then_env; fall=then_fall
        elif cond_val==0:
            result=else_env; fall=else_fall if st.els else True
        else:
            candidates=[]
            if then_fall: candidates.append(then_env)
            if st.els:
                if else_fall: candidates.append(else_env)
            else:
                # path where cond false: else_env (unchanged aside constraints)
                candidates.append(else_env)
            if candidates:
                result=merge_envs(candidates); fall=True
            else:
                result=then_env; fall=False
        env.clear(); env.update(result)
        return fall
    def apply_condition_constraints(self,cond,env,truth=True):
        if not cond: return
        a,b=cond; toks=self.tu.tokens
        if a>=b: return
        # Simple patterns:
        # strip outer parens
        while a+1<b and toks[a].s=='(' and self.tu.match.get(a)==b-1:
            a+=1; b-=1
        # !expr
        if toks[a].s=='!':
            self.apply_condition_constraints((a+1,b),env,truth=not truth); return
        # var
        if b-a==1 and toks[a].kind=='id' and a in self.ctx.token_var:
            var=self.ctx.token_var[a]; st=self.state_for(env,var)
            if var.pointer_level>0 or var.is_array:
                st['ptr']='nonnull' if truth else 'null'
                if not truth:
                    st['known']=0; st['known_tok']=toks[a]
                else:
                    if st.get('known')==0: st['known']=None
            else:
                # numeric var truth implies nonzero - clear known zero, false implies zero
                if truth:
                    if st.get('known')==0: st['known']=None
                else:
                    st['known']=0
            return
        # var op const
        # find top comparison operator
        op_idx=None; depth=0
        for k in range(a,b):
            s=toks[k].s
            if s in ('(','['): depth+=1
            elif s in (')',']'): depth-=1
            elif depth==0 and s in ('==','!='):
                op_idx=k; break
        if op_idx is not None:
            left=(a,op_idx); right=(op_idx+1,b); op=toks[op_idx].s
            # determine which side is var simple and other const
            for (va,vb),(ca,cb) in [(left,right),(right,left)]:
                if vb-va==1 and va in self.ctx.token_var:
                    cval=self.eval_range(ca,cb,env)
                    if cval is not None:
                        var=self.ctx.token_var[va]; st=self.state_for(env,var)
                        eq_true = (op=='==')==truth
                        # if equality holds (var==c true or var!=c false)
                        if eq_true:
                            st['known']=cval
                            if cval==0 and (var.pointer_level>0): st['ptr']='null'
                        else:
                            if st.get('known')==cval: st['known']=None
                            if cval==0 and var.pointer_level>0: st['ptr']='nonnull'
                    break
    def exec_loop(self,st,env):
        toks=self.tu.tokens
        if st.kind=='for':
            # ranged for: init contains ':' - exec as expr will parse decl etc
            if st.init: self.exec_expr(st.init[0],st.init[1],env, top_statement=True)
            if st.cond and st.cond[0]<st.cond[1]: self.exec_expr(st.cond[0],st.cond[1],env)
            # Special array loop check
            self.check_for_loop_array(st,env)
            body_env=clone_env(env)
            # Applying condition true constraints for body
            if st.cond: self.apply_condition_constraints(st.cond, body_env, truth=True)
            fall=True
            if st.body:
                self.exec_stmt(st.body, body_env)
            if st.inc: self.exec_expr(st.inc[0],st.inc[1],body_env)
            # After loop, merge env (before body) and body_env (vars modified may have loop values - merge will clear knowns that differ, conditions false constraint to env)
            merged=merge_envs([env,body_env])
            # Apply cond false for vars where simple var< const etc not represented - skip.
            env.clear(); env.update(merged)
            return stmt_fallthrough(self.tu,st,self.analyzer)
        if st.kind=='while':
            if st.cond: self.exec_expr(st.cond[0],st.cond[1],env)
            body_env=clone_env(env)
            if st.body: self.exec_stmt(st.body,body_env)
            merged=merge_envs([env,body_env]); env.clear(); env.update(merged)
            return stmt_fallthrough(self.tu,st,self.analyzer)
        if st.kind=='do':
            body_env=clone_env(env)
            if st.body: self.exec_stmt(st.body,body_env)
            if st.cond: self.exec_expr(st.cond[0],st.cond[1],body_env)
            merged=merge_envs([env,body_env]); env.clear(); env.update(merged)
            return stmt_fallthrough(self.tu,st,self.analyzer)
        if st.kind=='switch':
            if st.cond: self.exec_expr(st.cond[0],st.cond[1],env)
            body_env=clone_env(env)
            if st.body: self.exec_stmt(st.body,body_env)
            merged=merge_envs([env,body_env]); env.clear(); env.update(merged)
            return True
        return True
    def on_scope_exit(self,env,close_tok,scope_end=None):
        # leak/invalid for allocations/locals in scope ending. Variables whose scope_end == scope_end (token index after })
        # At function end, EMIT leaks for allocated objects held by dying vars.
        for var in self.ctx.locals:
            if scope_end is not None and var.scope_end!=scope_end: continue
            st=env.get(id(var))
            if not st: continue
            if st.get('alloc_id') is not None and not st.get('freed') and not st.get('escaped') and not st.get('leak_reported'):
                # Ensure no other live variable (scope not ending) points to same alloc
                alloc_id=st['alloc_id']; other=False
                for ov in self.ctx.locals:
                    if ov is var: continue
                    ovst=env.get(id(ov))
