def merge_envs(envs):
    if not envs: return {}
    if len(envs)==1: return envs[0]
    keys=set()
    for e in envs: keys.update(e.keys())
    out={}
    for k in keys:
        states=[e.get(k) for e in envs if k in e]
        if len(states)==1:
            # var only existed in a branch (declared there) - outside branch it's scoped, dropping is handled by scope end; but if a var declared before branch it exists in all envs. Keep single state only if it's from... To be safe keep copy.
            st=dict(states[0]); 
            if isinstance(st.get('member_init'),dict): st['member_init']=dict(st['member_init'])
            out[k]=st; continue
        base=dict(states[0])
        if isinstance(base.get('member_init'),dict): base['member_init']=dict(base['member_init'])
        # init
        inits={s.get('init') for s in states}
        base['init']=inits.pop() if len(inits)==1 else 'maybe'
        # known
        knowns={s.get('known') for s in states}
        if len(knowns)!=1:
            base['known']=None; base['known_tok']=None; base['known_text']=None
        # string_len / ptr / freed / alloc
        for field in ('ptr','alloc_id','alloc_kind','alloc_group','string_len','alloc_size','local_addr'):
            vals={s.get(field) if not isinstance(s.get(field),VarInfo) else id(s.get(field)) for s in states}
            if len(vals)!=1:
                if field=='ptr': base[field]='unknown'
                elif field=='local_addr': base[field]=base.get(field)  # keep first? if different could false - set None
                # for local_addr differing set None
                if field=='local_addr': base[field]=None
                elif field!='ptr': base[field]=None if field not in ('alloc_id',) else base.get(field)
                # alloc_id keep if same? len !=1 means different alloc ids from branches - allocation could be either, keep first as representative but freed state merged below.
                if field=='alloc_id': base[field]=states[0].get(field)
        base['freed']=all(s.get('freed') for s in states)
        base['escaped']=any(s.get('escaped') for s in states)
        if any(s.get('freed') for s in states) and not base['freed']:
            base['maybe_freed']=True
        base['reported_uninit']=any(s.get('reported_uninit') for s in states)
        # member_init merge
        mall={}
        for s in states:
            for mk,mv in (s.get('member_init') or {}).items():
                mall.setdefault(mk,set()).add(mv)
        base['member_init']={mk:(list(v)[0] if len(v)==1 else 'maybe') for mk,v in mall.items()}
        out[k]=base
    return out

