                    full=self.access_text(access_start,subs[-1])
                    msg=f"Array '{arr_disp}' accessed at index {full}, which is out of bounds."
                else:
                    msg=f"Array '{base_display}[{size}]' accessed at index {ival}, which is out of bounds."
                locs=self._index_note_locs(s,env,prim)
                self.add_error(Error('arrayIndexOutOfBounds','error',msg,locs))
