            m=self.tu.match.get(j); 
            if m is None: break
            j=m-1
        return max(j,0)
    def access_text(self,start_idx,last_sub):
        # from start to end of last subscript (matching ])
        end=self.tu.match.get(last_sub['bracket_idx'], last_sub['range'][1])+1
        return tokens_text(self.tu.tokens[start_idx:end])
    def _index_note_locs(self,sub,env,prim):
        a,b=sub['range']
        # find first var token in range with known assignment info and known value used
        for idx in range(a,b):
            if idx in self.ctx.token_var:
                var=self.ctx.token_var[idx]; st=env.get(id(var))
                if st and st.get('known_tok') is not None and st.get('known') is not None:
                    kt=st['known_tok']; txt=st.get('known_text') or f"{var.name}={st['known']}"
                    return [Loc(kt.file,kt.line,kt.col,f"Assignment '{txt}', assigned value is {format_value(st['known'])}"), prim]
        return [prim]

