    # ---- Token navigation helpers ----
    def find_primary_end(self,i,end):
        toks=self.tu.tokens
        if i>=end: return i
        t=toks[i]
        # unary signs
        if t.s in ('-','+','!','~','++','--','*','&') and t.s!='&' or t.s in ('-','+','!','~','++','--'):
            return self.find_primary_end(i+1,end)
        if t.s=='(':
            m=self.tu.match.get(i)
            if m is None: return i+1
            j=m+1
        elif t.s=='new':
            j=self.skip_new(i,end)
        else:
            j=i+1
        # suffixes
        while j<end:
            if toks[j].s=='[':
                m=self.tu.match.get(j); 
                if m is None: break
                j=m+1; continue
            if toks[j].s=='(':
                m=self.tu.match.get(j)
                if m is None: break
                j=m+1; continue
            if toks[j].s in ('.','->') and j+1<end:
                j+=2; continue
            if toks[j].s in ('++','--'):
                j+=1; continue
            if toks[j].s=='::' and j+1<end:
                j+=2; continue
            break
        return j
