            if m is not None:
                # peek after: if token after is id/type keyword, it was placement. If the tokens inside are a type and after is '['/'('/operator, then it was type.
                after=m+1
                if after<end and (toks[after].kind=='id' or toks[after].s in TYPE_KEYWORDS):
                    j=after
                else:
                    return m+1
