                    j+=1
                continue
            j+=1
        if j<end and toks[j].s=='[':
            m=self.tu.match.get(j); 
            if m is not None: j=m+1
        if j<end and toks[j].s in ('(','{'):
            m=self.tu.match.get(j)
            if m is not None: j=m+1
        return j
