            if toks[j].s in ('.','->') and j+1<end and toks[j+1].kind=='id':
                members.append({'op':toks[j].s,'op_idx':j,'name':toks[j+1].s,'name_idx':j+1,'subs_before':len(subs)})
                j+=2; continue
