        if toks[a].s=='&' and a+1<b and (a+1 in self.ctx.token_var):
            var=self.ctx.token_var[a+1]; tok=toks[a]
            self.add_error(Error('autovarInvalidDeallocation','error',"Deallocation of an auto-variable results in undefined behaviour.",[Loc(tok.file,tok.line,tok.col,'')]))
            return
        if b-a==1 and a in self.ctx.token_var:
            var=self.ctx.token_var[a]; tok=toks[a]; st=self.state_for(env,var)
