            if st.get('string_tok') is not None and not st.get('_writable_string_array'):
                stok=st['string_tok']; lit=stok.s
                msg=f'Deallocation of a pointer pointing to a string literal ({lit}) results in undefined behaviour.'
                prim=Loc(tok.file,tok.line,tok.col,'Deallocating memory that was not dynamically allocated')
                locs=[]
                # assignment note: string token location, text s="hi"
                txt=st.get('known_text') or f"{var.name}={lit}"
                locs=[Loc(stok.file,stok.line,stok.col,f"Assignment '{txt}', assigned value is {lit}"), prim]
                self.add_error(Error('autovarInvalidDeallocation','error',msg,locs))
                st['freed']=True; return
