            if isinstance(st.get('local_addr'),VarInfo):
                la=st['local_addr']
                msg=f"Deallocation of an auto-variable ({la.name}) results in undefined behaviour." if is_delete else "Deallocation of an auto-variable results in undefined behaviour."
                prim=Loc(tok.file,tok.line,tok.col,'Deallocating memory that was not dynamically allocated')
                locs=[]
                if st.get('local_addr_tok') is not None:
                    at=st['local_addr_tok']; locs.append(Loc(at.file,at.line,at.col,'Address of variable taken here.'))
                locs.append(prim)
                self.add_error(Error('autovarInvalidDeallocation','error',msg,locs))
                st['freed']=True; return
            # Alloc state
            if st.get('alloc_id') is not None:
                # Used closed file for double fclose comes first - handled below if already freed.
                alloc_kind=st.get('alloc_kind')
                expected_kind=None
                if is_delete:
                    expected_kind='new[]' if delete_array else 'new'
                elif fname=='free': expected_kind='malloc'
                elif fname=='fclose': expected_kind='fopen'
                elif fname=='close': expected_kind='open'
                elif fname=='closedir': expected_kind='opendir'
                else:
                    # Library dealloc group determines expected based group. Our lib.dealloc maps fname->group (memory/resource name). Compare group instead.
                    expected_kind=None
                if st.get('freed'):
