                    if alloc_kind in ('fopen',) or (st.get('alloc_group') not in (None,'memory') and fname=='fclose'):
                        self.add_error(Error('useClosedFile','error',"Used file that is not opened.",[Loc(tok.file,tok.line,tok.col,'')]))
                        msg=f"Resource handle '{var.name}' freed twice."
                    else:
                        msg=f"Memory pointed to by '{var.name}' is freed twice."
                    prim=Loc(tok.file,tok.line,tok.col,msg)
                    locs=[]
                    if st.get('free_tok') is not None:
                        ft=st['free_tok']; locs.append(Loc(ft.file,ft.line,ft.col,msg))
                    locs.append(prim)
                    self.add_error(Error('doubleFree','error',msg,locs,symbol=var.name))
                    return
                # mismatch?
                mismatch=False
                if expected_kind is not None and alloc_kind is not None and alloc_kind!=expected_kind:
                    # Special: realloc kind is malloc in our alloc map, calloc also malloc kind. strdup kind malloc. fine.
                    mismatch=True
                if mismatch:
                    msg=f"Mismatching allocation and deallocation: {var.name}"
                    prim=Loc(tok.file,tok.line,tok.col,msg)
                    locs=[]
                    if var.name_tok is not None:
                        locs.append(Loc(var.name_tok.file,var.name_tok.line,var.name_tok.col,msg))
                    locs.append(prim)
                    self.add_error(Error('mismatchAllocDealloc','error',msg,locs,symbol=var.name))
                # uninitdata for delete of uninitialized object
                if is_delete and st.get('data_init') is False:
                    self.add_error(Error('uninitdata','error',f"Memory is allocated but not initialized: {var.name}",[Loc(tok.file,tok.line,tok.col,'')],symbol=var.name))
                # mark aliases freed
                aid=st['alloc_id']
                for ov in list(self.ctx.locals)+list(self.tu.globals):
                    os_=env.get(id(ov))
                    if os_ and os_.get('alloc_id')==aid:
                        os_['freed']=True; os_['free_tok']=tok
