                return
            # Unknown pointer param etc: mark var as freed with a pseudo alloc so second free is doubleFree if same var and no reassignment? Test h(p){free(p); free(p);} - probably cppcheck would report doubleFree. Track freed flag separately in state '_freed_unknown'
            if st.get('_freed_unknown'):
                msg=f"Memory pointed to by '{var.name}' is freed twice."
                prim=Loc(tok.file,tok.line,tok.col,msg); locs=[]
                if st.get('free_tok') is not None:
                    ft=st['free_tok']; locs.append(Loc(ft.file,ft.line,ft.col,msg))
                locs.append(prim)
                self.add_error(Error('doubleFree','error',msg,locs,symbol=var.name)); return
            st['_freed_unknown']=True; st['free_tok']=tok; st['freed']=True
            return
        # Complex arg expressions ignored
    def handle_delete(self,idx,end,env):
        toks=self.tu.tokens; j=idx+1; is_array=False
        if j<end and toks[j].s=='[':
            m=self.tu.match.get(j); is_array=True; j=(m+1 if m else j+1)
        pend=self.find_primary_end(j,end)
        if pend>j:
            # exec primary for reads? handle_dealloc expects range
            self.handle_dealloc('delete[]' if is_array else 'delete', idx, (j,pend), env, is_delete=True, delete_array=is_array)
        return pend

