    def handle_call(self,name_idx,close_idx,env,value_used=True,object_info=None):
        toks=self.tu.tokens; name_tok=toks[name_idx]; fname=name_tok.s
        open_idx=name_idx+1
        # member calls: prev token . or ->, then fname is method name; object expression before has been processed? In our scan, when we reach name token after object var, we may have already processed object var as member access (our access pattern in exec_expr handles obj.member but if followed by '(' the member access end is before '(' and then scan reaches member name - careful double. In exec_expr call detection, we treat indicator by scanning from name; object processing is done prior steps as simple object var token occurrence. For now treat fname as method, still allow library matching for std:: etc.
        # Split args
        arg_ranges=[]
        if open_idx<close_idx:
            segs=split_top_range(toks,open_idx+1,close_idx,',')
            arg_ranges=[x for x in segs if x[0]<x[1]]
        # Library function info
        libfunc=self.lib.functions.get(fname)
        # Process args: for each arg, exec_expr with special handling for &var (exec_expr's & handling) and arrays.
        # But for args that are alloc dealloc or library functions, processing arg tokens will trigger uninit reads for scalar vars appropriately, array bases are skipped for element read in generic scan (as decided), and subsequent lib arg checks handle array data uninit if needed.
        for (a,b) in arg_ranges:
            self.exec_expr(a,b,env)
        # CheckLibrary
        if self.settings.check_library:
            self.check_library_call(name_idx,fname,libfunc,arg_ranges,env)
        # Known alloc/dealloc functions by library alloc/dealloc maps
        if fname in self.lib.dealloc:
            if arg_ranges:
                self.handle_dealloc(fname,name_idx,arg_ranges[0],env, is_delete=False)
            # after dealloc, do not do generic escape
            return
        # Stdio closed file check for known FILE functions (except fclose already dealloc handled separately above because fclose in dealloc map - but useClosedFile double case is handled in handle_dealloc)
        file_funcs={'fgets','fputs','fread','fwrite','fprintf','fscanf','fseek','ftell','rewind','feof','fflush','fgetc','fputc','getc','putc'}
        if fname in file_funcs:
