        if toks[a].s=='&':
            inner,_=self.arg_type_of_range(a+1,b,env)
            return f"'{inner} *'" if inner else "'int *'", 'pointer'
        if b-a==1:
            t=toks[a]
            if t.kind=='string': return "'char *'",'charptr'
            if t.kind=='char': return "'int'",'int'
            if t.kind=='num':
                v=parse_number_token(t)
