    def check_duplicate_if(self,prev,st,env):
        toks=self.tu.tokens
        if not prev.cond or not st.cond: return
        prev_text=tokens_text(toks[prev.cond[0]:prev.cond[1]])
        text=tokens_text(toks[st.cond[0]:st.cond[1]])
        if prev_text!=text: return
        # Check if any assignment to vars in condition between prev cond and this cond (in prev body / between) - scan tokens prev.cond end to st.cond[0] for assignment to any var token name in condition
        cond_vars={toks[k].s for k in range(st.cond[0],st.cond[1]) if toks[k].kind=='id'}
        for k in range(prev.cond[1], st.cond[0]):
            if toks[k].kind=='id' and toks[k].s in cond_vars and k+1 < len(toks) and toks[k+1].s in ('=','+=','-=','*=','/=','%=','++','--'):
                return
            if toks[k].s in ('++','--') and k+1 < len(toks) and toks[k+1].s in cond_vars:
                return
        # Location: first token of current condition
        cur_tok=toks[st.cond[0]]; prev_tok=toks[prev.cond[0]]
        prev_fall=stmt_fallthrough(self.tu,prev.then,self.analyzer) if prev.then else True
        if prev.then and not prev_fall:
            msg=f"Identical condition '{text}', second condition is always false"
            prim=Loc(cur_tok.file,cur_tok.line,cur_tok.col,f"Testing identical condition '{text}'")
            locs=[Loc(prev_tok.file,prev_tok.line,prev_tok.col,f"If condition '{text}' is true, the function will return/exit"), prim]
            self.add_error(Error('identicalConditionAfterEarlyExit','warning',msg,locs),require=['warning'])
        else:
            msg="The if condition is the same as the previous if condition"
            prim=Loc(cur_tok.file,cur_tok.line,cur_tok.col,'Second condition')
            locs=[Loc(prev_tok.file,prev_tok.line,prev_tok.col,'First condition'),prim]
            self.add_error(Error('duplicateCondition','style',msg,locs),require=['style'])

