                    self.handle_call(i,close,env,value_used=value_used)
                    i=close+1; continue
            # unary deref
            if t.s=='*' and self.is_unary_op(i):
                lv2=self.parse_lvalue_at(i,b)
                if lv2 is not None:
                    self.process_lvalue_reads(lv2,env,write=False); i=lv2['end']; continue
