            if i in self.ctx.token_var:
                var=self.ctx.token_var[i]
                self.process_simple_var_token(i,var,env)
                i+=1; continue
            # Member name in a chain that wasn't caught (bare member / after .) : skip
            i+=1
    def process_simple_var_token(self,idx,var,env):
        toks=self.tu.tokens
        # Function names resolve to var if function pointer var called is handled by call detection before this (we are here because not followed '(')
        if var.is_array:
            # Record usage but not element read in generic context
            self.read_events.append({'var':var,'idx':idx,'kind':'array_use'})
            return
        # Struct var: standalone read of struct value. If its type known, it can generate uninit for struct members (handled in check_return and assignment RHS contexts). In generic expression, reading whole struct counts as read - if uninit, process scalar read will emit uninitvar name, but reference also emits structMember. This might false positive for passing struct by pointer decay irrelevant. Keep scalar read for struct only if next/prev suggests value use (operators/return assignment given handled via exec ranges) - generic scan can't know. We'll treat struct var like scalar for now; class objects with init default 'init' in state won't emit.
        self.process_scalar_read(idx,var,env)
    def process_access_read(self,lv,env):
        toks=self.tu.tokens; var=lv['var']; members=lv.get('members',[]); subs=lv.get('subs',[])
        # First process lvalue reads (array bounds / deref) with read_data True
        self.process_lvalue_reads(lv,env,write=False)
