        if members:
            # if subs exist, process_array... already invokes member read for element; avoid duplicate reported via reported set.
            has_subs_after=any(s['bracket_idx']>members[-1]['name_idx'] for s in subs)
            if not has_subs_after:
                self.check_member_read(var,lv['var_idx'],members,env)
                self.read_events.append({'var':var,'idx':lv['var_idx'],'kind':'member','member':members[-1]['name']})
    def check_increment_bool(self,lv,op_idx,env,post=True):
        var=lv.get('var')
