            tok=self.tu.tokens[op_idx]
            if post:
                msg="Incrementing a variable of type 'bool' with postfix operator++ is deprecated by the C++ Standard. You should assign it the value 'true' instead."
            else:
                msg="Incrementing a variable of type 'bool' with prefix operator++ is deprecated by the C++ Standard. You should assign it the value 'true' instead." if self.tu.tokens[op_idx].s=='++' else "Incrementing a variable of type 'bool' is not allowed."
                # exact prefix messages unknown - keep post message generic for ++; -- bool maybe different.
                msg="Incrementing a variable of type 'bool' with postfix operator++ is deprecated by the C++ Standard. You should assign it the value 'true' instead."
