    def check_binary_operator(self,op_idx,range_a,range_b,env):
        toks=self.tu.tokens; op=toks[op_idx].s; optok=toks[op_idx]
        # Skip if operator is inside a type/template context? Our exec only expressions.
        # Find immediate operand ranges (primary levels)
        left_a=self.find_left_primary_start(op_idx,range_a); left_b=op_idx
        right_a=op_idx+1
        if right_a>=range_b: return
        # right primary may start with unary -/+ etc
        right_b=self.find_primary_end(right_a,range_b) if toks[right_a].s not in ('-','+','!','~') else self.find_primary_end(right_a+1,range_b)
        lval=self.eval_range(left_a,left_b,env); rval=self.eval_range(right_a,right_b,env)
        ltext=tokens_text(toks[left_a:left_b]); rtext=tokens_text(toks[right_a:right_b])
        # Duplicate expression
        if op in ('-','/','%','==','!=','<','>','<=','>=','&&','||','&','|','^'):
            if ltext and ltext==rtext and not any(t.s in ('++','--','(') for t in toks[left_a:left_b]+toks[right_a:right_b]):
                # Avoid 0==0 etc literals duplicate? ast would... check values numeric same literal maybe still duplicateExpression? If both numeric literals and op == etc, cppcheck knownCondition etc. Skip if both literal nums.
                if not (toks[left_a].kind=='num' and toks[right_a].kind=='num'):
                    self.add_error(Error('duplicateExpression','style',f"Same expression on both sides of '{op}'.",[Loc(optok.file,optok.line,optok.col,'')]),require=['style','warning'])
        # Zerodiv
        if op in ('/','%'):
            if rval==0:
                prim=Loc(optok.file,optok.line,optok.col,'Division by zero')
                locs=[prim]
                # note from first var in right operand with known assignment
                for k in range(right_a,right_b):
                    if k in self.ctx.token_var:
                        var=self.ctx.token_var[k]; st=env.get(id(var))
                        if st and st.get('known_tok') is not None and st.get('known')==0:
                            kt=st['known_tok']; txt=st.get('known_text') or f"{var.name}=0"; locs=[Loc(kt.file,kt.line,kt.col,f"Assignment '{txt}', assigned value is 0"),prim]; break
                self.add_error(Error('zerodiv','error',"Division by zero.",locs))
            return
        # Shifts / overflow
        if op in ('<<','>>'):
            if rval is not None and isinstance(rval,(int,float)):
                if rval<0:
                    self.add_error(Error('shiftNegative','error',"Shifting by a negative value is undefined behaviour",[Loc(optok.file,optok.line,optok.col,'')]))
                    return
                width=self.infer_expr_bitwidth(left_a,left_b,env)
                if width is not None and rval>=width and self.settings.platform_name!='unspecified':
                    self.add_error(Error('shiftTooManyBits','error',f"Shifting {width}-bit value by {int(rval)} bits is undefined behaviour",[Loc(optok.file,optok.line,optok.col,'')]))
            # integer overflow for signed left shift handled below in generic arithmetic if lval/rval known
            self.check_int_overflow(op,optok,left_a,left_b,right_a,right_b,lval,rval,env)
            return
        if op in ('+','-','*'):
            self.check_int_overflow(op,optok,left_a,left_b,right_a,right_b,lval,rval,env)
            return
        if op in ('==','!=','<','>','<=','>='):
            self.check_comparison(op,optok,left_a,left_b,right_a,right_b,lval,rval,env)
            return
        if op in ('&&','||'):
            # known condition for &&/|| of known bool? duplicates already. Skip
            return
    def infer_expr_bitwidth(self,a,b,env):
        toks=self.tu.tokens
        # single var / literal
        if b-a==1 and a in self.ctx.token_var:
            var=self.ctx.token_var[a]
            names=[t.s for t in var.type_toks]
            if 'long' in names and names.count('long')>=2: return self.settings.sizes.get('long long',64)
            if 'long' in names: return self.settings.sizes.get('long',64)
            if 'short' in names: return self.settings.sizes.get('short',16)
            if 'char' in names: return self.settings.sizes.get('char',8)
            return self.settings.sizes.get('int',32)
        if b-a>=1 and toks[a].kind=='num':
            # suffix L/LL
            if re.search(r'LL$',toks[a].s,re.I): return self.settings.sizes.get('long long',64)
            if re.search(r'L$',toks[a].s,re.I): return self.settings.sizes.get('long',64)
            return self.settings.sizes.get('int',32)
        return self.settings.sizes.get('int',32)
    def is_unsigned_range(self,a,b,env):
        toks=self.tu.tokens
        if b-a==1 and a in self.ctx.token_var:
            var=self.ctx.token_var[a]; return var.is_unsigned or var.elem_type in ('size_t','uint32_t','uint64_t','uint16_t','uint8_t')
        if b-a==1 and toks[a].kind=='num': return bool(re.search(r'U$|UL$|ULL$',toks[a].s,re.I))
        return False
    def check_int_overflow(self,op,optok,la,lb,ra,rb,lval,rval,env):
        if lval is None or rval is None: return
        if isinstance(lval,float) or isinstance(rval,float): return
        if self.is_unsigned_range(la,lb,env) or self.is_unsigned_range(ra,rb,env): return
        width=self.infer_expr_bitwidth(la,lb,env)
        # If either operand has long width, use max
        width=max(width or 32, self.infer_expr_bitwidth(ra,rb,env) or 32)
        if self.settings.platform_name=='unspecified':
            # shift overflow was skipped unspecified in samples; arithmetic overflow maybe also skipped? We'll skip if unspecified
            return
        try:
            if op=='+': result=int(lval)+int(rval)
            elif op=='-': result=int(lval)-int(rval)
            elif op=='*': result=int(lval)*int(rval)
            elif op=='<<':
                if rval<0 or rval>10000: return
                result=int(lval)<<int(rval)
            elif op=='>>': return
            else: return
        except Exception: return
        maxv=(1<<(width-1))-1; minv=-(1<<(width-1))
        if result>maxv or result<minv:
            expr=tokens_text(self.tu.tokens[la:lb])+op+tokens_text(self.tu.tokens[ra:rb])
            self.add_error(Error('integerOverflow','error',f"Signed integer overflow for expression '{expr}'.",[Loc(optok.file,optok.line,optok.col,'')]))
    def check_comparison(self,op,optok,la,lb,ra,rb,lval,rval,env):
        toks=self.tu.tokens
        # unsigned <0 / >=0
        if (op=='<' and rval==0 and self.is_unsigned_range(la,lb,env)) or (op=='>' and lval==0 and self.is_unsigned_range(ra,rb,env)):
            expr_text=tokens_text(toks[la:lb]) if op=='<' else tokens_text(toks[ra:rb])
            self.add_error(Error('unsignedLessThanZero','style',f"Checking if unsigned expression '{expr_text}' is less than zero.",[Loc(optok.file,optok.line,optok.col,'')],symbol=expr_text),require=['style'])
            return
        if (op=='>=' and rval==0 and self.is_unsigned_range(la,lb,env)):
            expr_text=tokens_text(toks[la:lb])
            # Error id/message deduced: "unsignedPositive" ??? need check errorlist. Use known from errorlist template quickly by searching ERROR_DEFS not msg. We'll assume id 'unsignedPositive' and message:
            self.add_error(Error('unsignedPositive','style',f"Checking if unsigned expression '{expr_text}' is positive.",[Loc(optok.file,optok.line,optok.col,'')],symbol=expr_text),require=['style'])
            return
        # bool comparisons
        bool_side=None; int_side=None; int_val=None; int_tok_idx=None
        for (sa,sb,other_a,other_b,other_val) in [(la,lb,ra,rb,rval),(ra,rb,la,lb,lval)]:
            if sb-sa==1 and sa in self.ctx.token_var and self.ctx.token_var[sa].is_bool:
                if isinstance(other_val,(int,float)) and other_val not in (0,1):
                    bool_side=(sa,sb); int_side=(other_a,other_b); int_val=other_val; int_tok_idx=other_a; break
        if bool_side is not None:
            if op in ('==','!=','<','>','<=','>='):
                # compareBoolExpressionWithInt at operator only for ==/!=? In sample b==2.
                # errorlist: compareBoolExpressionWithInt is for bool expression compared with int other than 0/1.
                # cppcheck also has comparisonOfBoolWithInvalidComparator for relational ops - but bool==2 used compareBoolExpressionWithInt.
                if op in ('==','!='):
                    self.add_error(Error('compareBoolExpressionWithInt','warning',"Comparison of a boolean expression with an integer other than 0 or 1.",[Loc(optok.file,optok.line,optok.col,'')]),require=['warning'])
                # compareValueOutOfTypeRangeError at literal token, condition always false if == and value out bool range; if != always true
                if self.settings.platform_name!='unspecified':
                    ltok=toks[int_tok_idx]
                    outcome = (lval==rval) if op=='==' else True
                    always = 'true' if (op=='!=' or (op not in ('==',) and False)) else 'false'
                    # For == always false, != always true.
                    msg=f"Comparing expression of type 'bool' against value {format_value(int_val)}. Condition is always {always}."
                    self.add_error(Error('compareValueOutOfTypeRangeError','style',msg,[Loc(ltok.file,ltok.line,ltok.col,'')]),require=['style'])
                return
        # known condition true/false: if either var known and comparison can be evaluated fully and result known
        if lval is not None and rval is not None:
            res={'==':lval==rval,'!=':lval!=rval,'<':lval<rval,'<=':lval<=rval,'>':lval>rval,'>=':lval>=rval}[op]
            # Only report if a side is a variable with known assignment (not both literals) and not a duplicateExpression already (if texts identical, duplicate reported - known condition may also be? Skip if same text)
            if tokens_text(toks[la:lb])==tokens_text(toks[ra:rb]): return
            known_var=None; known_st=None
            for (sa,sb) in [(la,lb),(ra,rb)]:
                if sb-sa==1 and sa in self.ctx.token_var:
                    var=self.ctx.token_var[sa]; st=env.get(id(var))
                    if st and st.get('known_tok') is not None:
                        known_var=var; known_st=st; break
            if known_var is None: return
            comp_text=f"{tokens_text(toks[la:lb])} {op} {tokens_text(toks[ra:rb])}"
            msg=f"The comparison '{comp_text}' is always {'true' if res else 'false'}."
            prim=Loc(optok.file,optok.line,optok.col,msg); locs=[]
            kt=known_st['known_tok']
            locs=[Loc(kt.file,kt.line,kt.col,f"'{known_var.name}' is assigned value '{format_value(known_st.get('known'))}' here."), prim]
            self.add_error(Error('knownConditionTrueFalse','style',msg,locs),require=['style'])
    def check_return_expr(self,a,b,env,ret_tok):
        toks=self.tu.tokens
        # Check returning local address/lifetime / freed pointer / reference
        # Strip parens
        aa,bb=a,b
        while aa+1<bb and toks[aa].s=='(' and self.tu.match.get(aa)==bb-1:
            aa+=1; bb-=1
        # &var
        if aa<bb and toks[aa].s=='&':
            lv=self.parse_lvalue_at(aa+1,bb)
            if lv and lv.get('var') is not None:
                var=lv['var']
                if not var.is_global and not var.is_param and not var.is_static:
                    target_tok=toks[lv['var_idx']]
                    msg=f"Returning pointer to local variable '{var.name}' that will be invalid when returning."
                    prim=Loc(target_tok.file,target_tok.line,target_tok.col,msg)
                    locs=[Loc(target_tok.file,target_tok.line,target_tok.col,'Address of variable taken here.'), Loc(var.name_tok.file,var.name_tok.line,var.name_tok.col,'Variable created here.'), prim]
                    self.add_error(Error('returnDanglingLifetime','error',msg,locs))
                return
        if bb-aa==1 and aa in self.ctx.token_var:
            var=self.ctx.token_var[aa]; st=env.get(id(var)); tok=toks[aa]
            # freed pointer returned
            if st and st.get('freed'):
                msg=f"Returning/dereferencing '{var.name}' after it is deallocated / released"
                prim=Loc(tok.file,tok.line,tok.col,msg); locs=[]
                if st.get('free_tok') is not None:
                    ft=st['free_tok']; locs.append(Loc(ft.file,ft.line,ft.col,msg))
                locs.append(prim)
                self.add_error(Error('deallocret','error',msg,locs,symbol=var.name))
                return
            # local array returned as pointer
            ret_toks=[t.s for t in self.func.ret_toks]
            ret_is_ptr = ret_toks and ret_toks[-1]=='*' or '*' in ret_toks
            ret_is_ref = '&' in ret_toks or '&&' in ret_toks
            if var.is_array and not var.is_global and not var.is_static and ret_is_ptr:
                msg=f"Returning pointer to local variable '{var.name}' that will be invalid when returning."
                prim=Loc(tok.file,tok.line,tok.col,msg)
                locs=[Loc(tok.file,tok.line,tok.col,'Array decayed to pointer here.'), Loc(var.name_tok.file,var.name_tok.line,var.name_tok.col,'Variable created here.'), prim]
                self.add_error(Error('returnDanglingLifetime','error',msg,locs))
                # also uninit handled in exec_expr after this (array token generic won't emit, so emit here if array uninit)
                if st and st.get('init')=='uninit' and not st.get('reported_uninit'):
                    self.process_scalar_read(aa,var,env)
                return
            if ret_is_ref and not var.is_global and not var.is_param and not var.is_static:
                self.add_error(Error('returnReference','error',"Reference to local variable returned.",[Loc(tok.file,tok.line,tok.col,'')]))
                return
            if ret_is_ptr and st and isinstance(st.get('local_addr'),VarInfo):
                la=st['local_addr']
                msg=f"Returning pointer to local variable '{la.name}' that will be invalid when returning."
                prim=Loc(tok.file,tok.line,tok.col,msg)
                locs=[]
                if st.get('local_addr_tok') is not None:
                    at=st['local_addr_tok']; locs.append(Loc(at.file,at.line,at.col,'Address of variable taken here.'))
                if la.name_tok is not None: locs.append(Loc(la.name_tok.file,la.name_tok.line,la.name_tok.col,'Variable created here.'))
                locs.append(prim)
                self.add_error(Error('returnDanglingLifetime','error',msg,locs))
                return
    def check_for_loop_array(self,st,env):
        # Pattern for loop: init declares/assigns i=start; cond i<=N or i<N etc; increment i++
        toks=self.tu.tokens
        if not st.cond or not st.body: return
        # We will let normal body execution handle array accesses with i known as initial value which won't trigger. To catch max iteration, after body execution we could re-evaluate array accesses in body with i=max. Here before body execution, set loop variable known to its max bound in a clone? Our caller in exec_loop calls this before exec body, but body execution then proceeds with env (which currently has initial state). To implement simply: scan body token range for array accesses of arrays with index == loop var and check bound vs max.
        # Determine loop var and max from condition: var < N => max=N-1, var <=N => max=N, N>var etc
        ca,cb=st.cond
        # Find comparison operator
        op_idx=None
        for k in range(ca,cb):
            if toks[k].s in ('<','<=','>','>='):
                op_idx=k; break
        if op_idx is None: return
        left=(ca,op_idx); right=(op_idx+1,cb); op=toks[op_idx].s
        var=None; var_idx=None; bound=None; maxv=None
        # left var, right const
        if left[1]-left[0]==1 and left[0] in self.ctx.token_var:
            var=self.ctx.token_var[left[0]]; var_idx=left[0]; bound=self.eval_range(right[0],right[1],env)
            if bound is not None:
                maxv=int(bound)-1 if op=='<' else int(bound) if op=='<=' else None
        elif right[1]-right[0]==1 and right[0] in self.ctx.token_var:
            var=self.ctx.token_var[right[0]]; var_idx=right[0]; bound=self.eval_range(left[0],left[1],env)
            if bound is not None:
                maxv=int(bound)-1 if op=='>' else int(bound) if op=='>=' else None
        if var is None or maxv is None: return
        # Scan body range for arr[var] accesses
        for idx in range(st.body.start,st.body.end):
            if idx in self.ctx.token_var and idx+3<st.body.end and toks[idx+1].s=='[' and toks[idx+2].s==var.name and toks[idx+3].s==']':
                arr=self.ctx.token_var[idx]; sizes=self.array_size_for_var(arr,env)
                if sizes and sizes[0] is not None and maxv>=sizes[0]:
                    bracket=toks[idx+1]; size=sizes[0]
                    msg=f"Array '{arr.name}[{size}]' accessed at index {maxv}, which is out of bounds."
                    prim=Loc(bracket.file,bracket.line,bracket.col,'Array index out of bounds')
                    cond_text=tokens_text(toks[ca:cb])
                    # condition note location = operator token? Sample col34 in for(i<=10) was '<=' token (?) It reported note at condition operator.
                    cond_tok=toks[op_idx]
                    locs=[Loc(cond_tok.file,cond_tok.line,cond_tok.col,f"Assuming that condition '{cond_text}' is not redundant"), prim]
