def format_value(v):
    if isinstance(v,float):
        if v.is_integer(): return str(int(v))
        return ('%f'%v).rstrip('0').rstrip('.') if '.' in ('%f'%v) else str(v)
    return str(v)

def compute_compound(old,op,rhs):
    if op=='+=': return old+rhs
    if op=='-=': return old-rhs
    if op=='*=': return old*rhs
    if op=='/=': return int(old/rhs) if rhs!=0 else None
    if op=='%=': return old%rhs if rhs!=0 else None
    if op=='<<=': return old<<int(rhs)
    if op=='>>=': return old>>int(rhs)
    if op=='&=': return int(old)&int(rhs)
    if op=='|=': return int(old)|int(rhs)
    if op=='^=': return int(old)^int(rhs)
    return None

def parse_format_specs(fmt):
    specs=[]; i=0
    while i<len(fmt):
        if fmt[i]!='%':
            i+=1; continue
        if i+1<len(fmt) and fmt[i+1]=='%':
            i+=2; continue
        j=i+1
        # flags
        while j<len(fmt) and fmt[j] in "-+ #0'": j+=1
        # width
        width=False
        if j<len(fmt) and fmt[j]=='*':
            width=True; specs_star=True; j+=1
            # * consumes an int argument - model as an extra spec? For arg count, printf("%*d", width, val) needs both. Our specs handling counts only one per %. To keep count, add a dummy int spec before.
            specs.append({'conv':'d','raw_conv':'*d','width':False,'length':'','no_arg':False,'star':True})
        else:
            startw=j
            while j<len(fmt) and fmt[j].isdigit(): j+=1
            width=(j>startw)
        if j<len(fmt) and fmt[j]=='.':
            j+=1
            if j<len(fmt) and fmt[j]=='*':
                j+=1; specs.append({'conv':'d','raw_conv':'*d','width':False,'length':'','no_arg':False,'star':True})
            else:
                while j<len(fmt) and fmt[j].isdigit(): j+=1
        length=''
        if fmt[j:j+2] in ('hh','ll'):
            length=fmt[j:j+2]; j+=2
        elif j<len(fmt) and fmt[j] in 'hljztL':
            length=fmt[j]; j+=1
        if j>=len(fmt): break
        conv=fmt[j]; j+=1
        raw=conv
        if conv=='[':
            # scanset ends ]
            k=j
            if k<len(fmt) and fmt[k]=='^': k+=1
            if k<len(fmt) and fmt[k]==']': k+=1
            while k<len(fmt) and fmt[k]!=']': k+=1
            j=k+1
        specs.append({'conv':conv,'raw_conv':length+conv,'width':width,'length':length,'no_arg':False})
        i=j
    return specs

def spec_expected_type(spec):
    c=spec['conv']; length=spec.get('length','')
    if c in ('d','i'):
        return ('long long' if length=='ll' else 'long' if length=='l' else 'int')
    if c in ('u','x','X','o'):
        return ('unsigned long long' if length=='ll' else 'unsigned long' if length=='l' else 'unsigned int')
    if c in ('f','F','e','E','g','G','a','A'):
        return 'double' if length!='L' else 'long double'
    if c=='c': return 'int'
    if c=='s': return 'char *'
    if c=='p': return 'void *'
    if c=='n': return 'int *'
    return None

def printf_err_id_for_spec(spec):
    c=spec['conv']
    if c=='s': return 'invalidPrintfArgType_s'
    if c=='n': return 'invalidPrintfArgType_n'
    if c=='p': return 'invalidPrintfArgType_p'
    if c in ('u','x','X','o'): return 'invalidPrintfArgType_uint'
    if c in ('d','i','c'): return 'invalidPrintfArgType_sint'
    if c in ('f','F','e','E','g','G','a','A'): return 'invalidPrintfArgType_float'
    return 'invalidPrintfArgType_sint'

def format_type_compatible(spec,actual_kind):
    c=spec['conv']
    if actual_kind=='unknown': return True
    if c in ('d','i','c'): return actual_kind in ('int','long','uint')
    if c in ('u','x','X','o'): return actual_kind in ('uint','int','long')
    if c in ('f','F','e','E','g','G','a','A'): return actual_kind=='double'
    if c=='s': return actual_kind in ('charptr','pointer')
    if c=='p': return actual_kind in ('pointer','charptr','int')
    if c=='n': return actual_kind=='pointer'
    return True

# ---------- TU level analysis ----------
def analyze_tu(analyzer, entry, language, tokens, preproc_errors):
    errors=list(preproc_errors or [])
    tu=TU(analyzer,entry,language,tokens,errors)
    # TU constructor stored errors list reference? It sets self.errors=[] separate - use tu.errors for subsequent and merge later.
    # Syntax validation
    config_str=getattr(entry,'_config_str','')
    # Number-number adjacency, invalid C etc determined below; bracket syntax has priority? If multiple syntax errors, cppcheck reports first encountered by tokenization phases - bracket validation is tokenizer step before checks. We'll prioritize bracket, then invalid C, then number adjacency.
    critical_err=None
    if tu.bracket_syntax:
        tok,ch=tu.bracket_syntax
        critical_err=Error('syntaxError','error',f"Unmatched '{ch}'. Configuration: '{config_str}'.",[Loc(tok.file,tok.line,tok.col,'')],rank=rank_for('syntaxError'),critical=True)
    if critical_err is None and language=='c':
        critical_err=check_invalid_c(tu)
    if critical_err is None:
        critical_err=check_number_number(tu)
    if critical_err is None:
        critical_err=check_unknown_macro_return(tu)
    if critical_err is not None:
        analyzer.critical_ids.add(critical_err.id)
        # Errors: preproc (missing includes) + critical. Order sorting by rank in driver will put invalid suppression/missing first as ranks.
        return tu, [critical_err]
    all_errors=[]
    # Global token simple checks
    all_errors.extend(check_global_tokens(tu,analyzer))
    # Classes checks (style/warning)
    all_errors.extend(check_classes(tu,analyzer))
    func_contexts=[]
    for func in tu.functions:
        if not func.is_definition: continue
        fa=FuncAnalyzer(tu,func,all_errors,analyzer)
        func_contexts.append(fa)
        try:
            fa.analyze()
        except Exception as e:
            # Avoid crashing whole run on internal bugs for a function - in production this hides bugs but keeps tool usable. During development, if CPPCHECK_DEBUG env, reraise.
            if os.environ.get('CPPCHECK_IMPL_DEBUG'):
                raise
    tu._func_contexts=func_contexts
    return tu,all_errors

def check_number_number(tu):
    toks=tu.tokens
    for i in range(len(toks)-1):
        if toks[i].kind=='num' and toks[i+1].kind=='num':
            t=toks[i]; return Error('syntaxError','error',"syntax error",[Loc(t.file,t.line,t.col,'')],rank=rank_for('syntaxError'),critical=True)
    # trailing stray num at top-level after a function/type (tokens after last } / ;) if it's only token left
    # Find last position: if tokens end with a number and previous token is '}' of a function, report.
    if toks and toks[-1].kind=='num':
        # ensure that this num is at top-level (brace depth 0 at its positon)
        depth=0
        for t in toks[:-1]:
            if t.s=='{': depth+=1
            elif t.s=='}': depth-=1
        if depth==0 and len(toks)>1 and toks[-2].s=='}':
            t=toks[-1]; return Error('syntaxError','error',"syntax error",[Loc(t.file,t.line,t.col,'')],rank=rank_for('syntaxError'),critical=True)
    return None

def check_unknown_macro_return(tu):
    toks=tu.tokens
    for i in range(1,len(toks)):
        if toks[i].s=='return' and toks[i-1].kind=='id' and toks[i-1].s not in KEYWORDS:
            # Ensure previous id is a local variable declaration name? It could be "x return" only as pattern. Check token before id is a type-ish id/keyword or *.
            if i>=2 and (toks[i-2].kind=='id' or toks[i-2].s in TYPE_KEYWORDS or toks[i-2].s=='*'):
                t=toks[i-1]
                return Error('unknownMacro','error',f"There is an unknown macro here somewhere. Configuration is required. If {t.s} is a macro then please configure it.",[Loc(t.file,t.line,t.col,'')],rank=rank_for('unknownMacro'),critical=True)
    return None

def check_invalid_c(tu):
    toks=tu.tokens
    # Top-level class/namespace/template patterns: they can also be inside functions? class local in C also invalid.
    for i,t in enumerate(toks):
        if t.s=='class' and i+2<len(toks) and toks[i+1].kind=='id' and toks[i+2].s in ('{',':'):
            code=f"{t.s}{toks[i+1].s}{toks[i+2].s}" if toks[i+2].s=='{' else f"{t.s} {toks[i+1].s} :"
            # Original for class C { was 'classC{'
            return Error('syntaxError','error',f"Code '{code}' is invalid C code.",[Loc(t.file,t.line,t.col,'')],critical=True)
        if t.s=='namespace' and i+2<len(toks) and toks[i+1].kind=='id' and toks[i+2].s=='{':
            code=f"namespace{toks[i+1].s}{{"
            return Error('syntaxError','error',f"Code '{code}' is invalid C code.",[Loc(t.file,t.line,t.col,'')],critical=True)
        if t.s=='template':
            return Error('syntaxError','error',"Code 'template<...' is invalid C code.",[Loc(t.file,t.line,t.col,'')],critical=True)
        # Reference declarator: type & name : token sequence id/typeword '&' id and next is '=' or ';' or ',' or ')' (parameter) and & is not binary - previous token is type word and before that is '(' ',' ';' '{' etc.
        if t.s=='&' and i>=1 and i+1<len(toks) and toks[i+1].kind=='id':
            prev=toks[i-1]
            if prev.s in TYPE_KEYWORDS or prev.kind=='id':
                # ensure this looks like decl: token before prev is a statement delimiter/open
                if i>=2 and toks[i-2].s in (';','{','(',')',','):
                    # code text: previous type text + '&' + ' ' + name
                    code=f"{prev.s}& {toks[i+1].s}"
                    return Error('syntaxError','error',f"Code '{code}' is invalid C code.",[Loc(t.file,t.line,t.col,'')],critical=True)
    return None

def check_global_tokens(tu,analyzer):
    errs=[]; toks=tu.tokens
    # Determine ranges inside function bodies to skip
    body_ranges=[(f.body_start,f.body_end) for f in tu.functions if f.body_start is not None]
    def in_body(idx):
        return any(a<=idx<=b for a,b in body_ranges)
    consts=tu._global_const_values()
    # Arrays map name -> global var
    i=0
    while i < len(toks):
        if in_body(i):
            i+=1; continue
        t=toks[i]
        # global array access
        if t.kind=='id' and t.s in tu.global_by_name and i+1<len(toks) and toks[i+1].s=='[':
            var=tu.global_by_name[t.s]
            if var.is_array and var.array_sizes:
                m=tu.match.get(i+1)
                if m:
                    v=eval_const_expr(toks[i+2:m],var_values=consts,sizeof_resolver=lambda inner,p=False: sizeof_of_tokens(tu,inner))
                    if isinstance(v,(int,float)):
                        size=var.array_sizes[0]
                        if size is not None:
                            btok=toks[i+1]
                            if int(v)<0:
                                errs.append(Error('negativeIndex','error',f"Array '{var.name}[{size}]' accessed at index {int(v)}, which is out of bounds.",[Loc(btok.file,btok.line,btok.col,'Negative array index')]))
                            elif int(v)>=size:
                                errs.append(Error('arrayIndexOutOfBounds','error',f"Array '{var.name}[{size}]' accessed at index {int(v)}, which is out of bounds.",[Loc(btok.file,btok.line,btok.col,'Array index out of bounds')]))
        if t.s in ('/','%') and i+1<len(toks):
            # right primary simple
            # use eval for next token(s) simple num/var/paren
            # Determine right end via local helper: if '(' then match, else next token
            rend=i+2
            if toks[i+1].s=='(':
                m=tu.match.get(i+1); rend=m+1 if m else i+2
            v=eval_const_expr(toks[i+1:rend],var_values=consts)
            if v==0:
                errs.append(Error('zerodiv','error',"Division by zero.",[Loc(t.file,t.line,t.col,'Division by zero')]))
        if t.s in ('<<','>>') and i>0 and i+1<len(toks):
            rv=eval_const_expr(toks[i+1:i+2],var_values=consts)
            lv=eval_const_expr(toks[i-1:i],var_values=consts)
            if isinstance(rv,(int,float)) and rv<0:
                errs.append(Error('shiftNegative','error',"Shifting by a negative value is undefined behaviour",[Loc(t.file,t.line,t.col,'')]))
            elif isinstance(rv,(int,float)) and rv>=32 and analyzer.settings.platform_name!='unspecified':
                errs.append(Error('shiftTooManyBits','error',f"Shifting 32-bit value by {int(rv)} bits is undefined behaviour",[Loc(t.file,t.line,t.col,'')]))
                if lv is not None:
                    expr=toks[i-1].s+t.s+toks[i+1].s
                    if int(lv)<<int(rv) > 2147483647:
                        errs.append(Error('integerOverflow','error',f"Signed integer overflow for expression '{expr}'.",[Loc(t.file,t.line,t.col,'')]))
        if t.s=='+' and i>0 and i+1<len(toks):
            lv=eval_const_expr(toks[i-1:i],var_values=consts); rv=eval_const_expr(toks[i+1:i+2],var_values=consts)
            if isinstance(lv,int) and isinstance(rv,int) and lv+rv>2147483647 and analyzer.settings.platform_name!='unspecified':
                expr=toks[i-1].s+t.s+toks[i+1].s
                errs.append(Error('integerOverflow','error',f"Signed integer overflow for expression '{expr}'.",[Loc(t.file,t.line,t.col,'')]))
        i+=1
    return errs

def check_classes(tu,analyzer):
    errs=[]; settings=analyzer.settings
    if tu.language!='c++': return errs
    for ci in tu.classes:
        if not ci.name: continue
        ctors=[m for m in ci.methods if m.is_constructor]
        # uninitMemberVar (warning) for each constructor that doesn't initialize a native/ptr member
        if settings.is_enabled('warning'):
            for ctor in ctors:
                if not ctor.is_definition: continue
                # Determine initialized members: ctor initializer list between param close and body '{' plus assignments in body (member = / this->member=)
                initialized=set()
                toks=tu.tokens
                if ctor.param_range:
                    # tokens between matching ')' of params (param_range end) and body_start
                    pclose=ctor.param_range[1]
                    for k in range(pclose+1, ctor.body_start):
                        if toks[k].kind=='id' and k+1<len(toks) and toks[k+1].s in ('(','{'):
                            initialized.add(toks[k].s)
                # assignments in body: tokens member name followed '=', or this->member =
                for k in range(ctor.body_start, ctor.body_end):
                    if toks[k].kind=='id' and k+1<len(toks) and toks[k+1].s=='=':
                        initialized.add(toks[k].s)
                for mem in ci.members:
                    # member with in-class initializer is initialized
                    if mem.init_range is not None or mem.init_toks: continue
                    if mem.is_static: continue
                    # only native/pointer/reference types: type keywords or pointer
                    tw=[t.s for t in mem.type_toks]
                    if not (mem.pointer_level>0 or mem.is_ref or any(w in TYPE_KEYWORDS for w in tw)):
                        continue
                    if mem.name not in initialized:
                        tok=ctor.name_tok
                        msg=f"Member variable '{ci.name}::{mem.name}' is not initialized in the constructor."
                        errs.append(Error('uninitMemberVar','warning',msg,[Loc(tok.file,tok.line,tok.col,'')],symbol=f"{ci.name}::{mem.name}"))
        # noExplicitConstructor (style): constructor with 1 parameter that is not explicit, not copy/move ctor*
        if settings.is_enabled('style'):
            for ctor in ctors:
                # one required param (params count where not default? treat exactly 1 param token group)
                if len(ctor.params)==1 and ctor.params[0].name!='' or len(ctor.params)==1:
                    if len(ctor.params)!=1: continue
                    # Skip if param type is same class (copy ctor)
                    ptoks=ctor.params[0].type_toks
                    if any(t.s==ci.name for t in ptoks): continue
                    if any(t.s=='explicit' for t in ctor.ret_toks): continue
                    tok=ctor.name_tok
                    msg=f"Class '{ci.name}' has a constructor with 1 argument that is not explicit."
                    errs.append(Error('noExplicitConstructor','style',msg,[Loc(tok.file,tok.line,tok.col,'')],symbol=ci.name))
        # noConstructor (style): class has private member vars and no constructor - errorlist msg says does not declare a constructor although it has private member variables
        if settings.is_enabled('style'):
            if not ctors and ci.members and not ci.is_struct:
                # Check members are private (default class). All members in our scan have no access stored for members - assume class members private if class.
                # Only native/ptr/reference members
                if any((m.pointer_level>0 or m.is_ref or any(t.s in TYPE_KEYWORDS for t in m.type_toks)) for m in ci.members):
                    tok=ci.name_tok
                    if tok:
                        msg=f"The class '{ci.name}' does not declare a constructor although it has private member variables which likely require initialization."
                        errs.append(Error('noConstructor','style',msg,[Loc(tok.file,tok.line,tok.col,'')],symbol=ci.name))
        # missingOverride (style): method in derived class with same name/params as virtual in base and no override keyword after params
        if settings.is_enabled('style') and tu.language=='c++' and settings.std_cpp!='c++03':
            for base_name,btok in ci.bases:
                base_ci=next((c for c in tu.classes if c.name==base_name),None)
                if not base_ci: continue
                for m in ci.methods:
                    for bm in base_ci.methods:
                        if bm.is_virtual and bm.name==m.name and not bm.is_constructor:
                            # override present in tokens between param close and ; or {
                            toks=tu.tokens
                            end_idx=m.body_start if m.is_definition else None
                            has_override=False
                            if m.param_range:
                                scan_end = m.body_start if m.is_definition else min(m.param_range[1]+10, len(toks))
                                for k in range(m.param_range[1]+1, scan_end if scan_end else len(toks)):
                                    if toks[k].s=='override': has_override=True
                                    if toks[k].s==';': break
                            if not has_override:
                                tok=m.name_tok
                                msg=f"The function '{m.name}' overrides a function in a base class but is not marked with a 'override' specifier."
                                prim=Loc(tok.file,tok.line,tok.col,'Function in derived class')
                                btok2=bm.name_tok
                                locs=[Loc(btok2.file,btok2.line,btok2.col,'Virtual function in base class'), prim]
                                errs.append(Error('missingOverride','style',msg,locs,symbol=m.name))
    # unusedStructMember (style) for class/struct members never used anywhere in TU.
    if settings.is_enabled('style'):
        # member names used as .member / ->member or bare in methods (token after ./->) count
        used_member_names=set()
        toks=tu.tokens
        for i,t in enumerate(toks):
            if t.s in ('.','->') and i+1<len(toks) and toks[i+1].kind=='id':
                used_member_names.add(toks[i+1].s)
        for ci in tu.classes:
            for mem in ci.members:
                if mem.name not in used_member_names:
                    # Also bare usage inside methods of same class would be token_var? Our token_var for methods doesn't map members. If name appears as identifier in method bodies, count as used.
                    found=False
                    for meth in ci.methods:
                        if meth.is_definition:
                            for k in range(meth.body_start,meth.body_end):
                                if toks[k].s==mem.name:
                                    found=True; break
                    if found: continue
                    # Only report for classes where... reference reports for private memers unused. For struct members that are public may also report? In tests struct S {int x;} unused member may be reported if no use (enable style). Keep.
                    tok=mem.name_tok
                    msg=f"class member '{ci.name}::{mem.name}' is never used."
                    errs.append(Error('unusedStructMember','style',msg,[Loc(tok.file,tok.line,tok.col,'')],symbol=f"{ci.name}::{mem.name}"))
    return errs

