def compute_active_checkers(settings, any_cpp, critical=False):
    if critical:
        return [False]*len(CHECKERS_DATA)
    groups=settings.enabled_groups()
    specials={
      'CheckBufferOverrun::arrayIndexThenCheck': ['style'],
      'CheckIO::invalidScanf': ['warning'],
      'CheckMemoryLeakNoVar::checkForUnsafeArgAlloc': ['__special_unsafe'],
    }
    active=[]
    for name,kind,tags,cpp_only in CHECKERS_DATA:
        if settings.check_config:
            ok=name in ('CheckBufferOverrun::analyseWholeProgram','CheckClass::analyseWholeProgram','CheckNullPointer::analyseWholeProgram','CheckUninitVar::analyseWholeProgram') or (name=='CheckUnusedFunctions::check' and 'unusedFunction' in groups)
            active.append(ok); continue
        if kind=='always':
            active.append(True); continue
        if kind=='cppalways':
            active.append(any_cpp); continue
        tags_eff=list(tags)
        if name in specials:
            tags_eff=specials[name]
        if cpp_only and not any_cpp:
            active.append(False); continue
        ok=True
        sev_tags=[t for t in tags_eff if t in ('style','warning','performance','portability')]
        if sev_tags and not any(t in groups for t in sev_tags): ok=False
        for tag in tags_eff:
            if not ok: break
            if tag in sev_tags: continue
            if tag=='__special_unsafe':
                if not (any_cpp and settings.inconclusive and 'warning' in groups): ok=False
            elif tag=='c++':
                if not any_cpp: ok=False
            elif tag=='inconclusive':
                if not settings.inconclusive: ok=False
            elif tag=='unusedFunction':
                if 'unusedFunction' not in groups: ok=False
            elif tag=='platform':
                if settings.platform_str=='unspecified': ok=False
            elif tag=='windows-platform':
                if not settings.platform_str.startswith('win'): ok=False
            elif tag=='safeChecks':
                ok=False
            elif tag=='notclang':
                if settings.clang: ok=False
            elif tag=='c++03':
                if name=='CheckStl::size':
                    if not (any_cpp and settings.std_cpp=='c++03'): ok=False
                elif name=='CheckClass::checkMissingOverride':
                    if not any_cpp or settings.std_cpp=='c++03': ok=False
                else:
                    if not any_cpp: ok=False
            elif tag=='c++11':
                if any_cpp:
                    if settings.std_cpp=='c++03': ok=False
                else:
                    if 'c99' not in tags_eff: ok=False
            elif tag=='c99':
                if not any_cpp and settings.std_c=='c89': ok=False
            elif tag=='c':
                if any_cpp: ok=False
            else:
                pass
        if settings.check_library and name=='CheckUnusedVar::checkFunctionVariableUsage':
            ok=True
        active.append(ok)
    return active

def make_checkers_report(settings, any_cpp, critical_ids):
    active=compute_active_checkers(settings, any_cpp, critical=bool(critical_ids))
    lines=[]
    if critical_ids:
        ids_str=', '.join(critical_ids)
        lines.append("Critical errors\n---------------\n")
        lines.append(f"There were critical errors ({ids_str}).\n")
        lines.append("These cause the analysis of the file to end prematurely.\n")
    else:
        lines.append("Critical errors\n---------------\n")
        lines.append("No critical errors encountered.\n")
        lines.append("Note: There might still have been non-critical bailouts which might lead to false negatives.\n")
    lines.append("\n\nOpen source checkers\n--------------------\n")
    for is_active,(name,kind,tags,cpp_only) in zip(active,CHECKERS_DATA):
        if is_active:
            lines.append(f"Yes  {name}\n")
        else:
            if tags:
                prefix=f"No   {name:<58}"
                lines.append(prefix+f"require:{','.join(tags)}\n")
            else:
                lines.append(f"No   {name}\n")
    return ''.join(lines)

