    errors.extend(getattr(analyzer,'ctu_errors',[]) or [])
    if not settings.is_enabled('unusedFunction'):
        return errors
    # Gather definitions and usages
    # Usage map name -> set of TU ids where used (call/other token occurrences excluding decl/def name tokens)
    usage={}
    all_defs=[]
    for tu in all_tus:
        for f in tu.functions:
            if f.is_definition and not f.is_method and not f.is_constructor and not f.is_destructor and not f.name.startswith('operator'):
                all_defs.append((tu,f))
