            # A usage if followed by '(' (call) or token is used as value (preceded by & / = / return / , / '(' ), but declarations prototypes have name_idx in def_name_indices includes prototypes (they are in tu.functions) so excluded.
            is_use=False
            if idx+1<len(toks) and toks[idx+1].s=='(':
                is_use=True
            elif idx>0 and toks[idx-1].s=='&':
                is_use=True
            if is_use:
                usage.setdefault(t.s,set()).add(id(tu))
    for tu,f in all_defs:
        if f.name=='main': continue
        # skip functions with C linkage? ret contains extern "C" - tokens not captured in ret (extern before?) skip if ret contains extern
        if any(t.s=='extern' for t in f.ret_toks): continue
        used_in=usage.get(f.name,set())
        tok=f.name_tok
        if not used_in:
            msg=f"The function '{f.name}' is never used."
            e=Error('unusedFunction','style',msg,[Loc(tok.file,tok.line,tok.col,'')],symbol=f.name,file0_marker=False); e.rank=rank_for('unusedFunction'); errors.append(e)
        elif used_in=={id(tu)} and not f.is_static:
            # Check if function is declared in a header (prototype with file different from definition file)
            declared_in_header=False
            for tu2 in all_tus:
                for pf in tu2.functions:
                    if pf.name==f.name and not pf.is_definition and pf.name_tok and pf.name_tok.file!=f.name_tok.file:
                        declared_in_header=True
