                msg=f"The function '{f.name}' should have static linkage since it is not used outside of its translation unit."
                e=Error('staticFunction','style',msg,[Loc(tok.file,tok.line,tok.col,'')],symbol=f.name,file0_marker=False); e.rank=rank_for('staticFunction'); errors.append(e)
    return errors

