        regex='^'+re.escape(pat).replace(r'\*\*/','(.*/)?').replace(r'\*\*','.*').replace(r'\*','[^/]*').replace(r'\?','[^/]')+'$'
        return re.match(regex,p) is not None or re.match(regex, os.path.basename(p)) is not None
