def is_ignored(settings, display):
    for pat in settings.ignored:
        patn=pat.rstrip('/') if pat!='/' else pat
        if '*' in pat or '?' in pat:
            if pattern_match_path(pat,display): return True
        else:
            if display==patn or os.path.basename(display)==patn or display.startswith(patn+'/') or ('/'+patn+'/') in ('/'+display+'/'):
