def resolve_addons(settings):
    resolved=[]
    for addon in settings.addons:
        kind,path_or_err=find_addon(settings,addon)
        if kind is None:
            return None,path_or_err
        if kind=='json':
            try:
                data=open(path_or_err,'rb').read().decode('latin-1')
                j=json.loads(data)
            except Exception as e:
                # picojson style approx
                near=''
                try:
