                    near=txt[1:] if len(txt)>1 else txt
                except: pass
                return None, f"Loading {addon} failed. syntax error at line 1 near: {near}\n"
            if not isinstance(j,dict) or 'script' not in j:
                return None, f"Loading {addon} failed. 'script' is missing.\n"
            if 'args' in j and not isinstance(j['args'],list):
                return None, f"Loading {addon} failed. 'args' must be an array.\n"
