    if settings.E:
        return 0
    # Whole program
    whole_errors=[]
    if not settings.check_config:
        whole_errors=whole_program_checks(analyzer,all_tus)
        # Whole addons
        if resolved_addons:
            whole_errors.extend(run_addons_whole(analyzer,resolved_addons))
    all_errors.extend(whole_errors)
    note_critical(all_errors)
    for cid in getattr(analyzer,'critical_ids',[]):
        if cid not in critical_ids_order: critical_ids_order.append(cid)
    # Global dedup preserve order
    deduped=[]; seen_keys=set()
    for e in all_errors:
        k=e.dedup_key()
        if k in seen_keys: continue
        seen_keys.add(k); deduped.append(e)
    all_errors=deduped
    # Suppression filtering
    filtered=[]
    suppressions_all=list(settings.suppressions)
    if settings.inline_suppr:
        suppressions_all.extend(analyzer.inline_suppressions)
    for e in all_errors:
        matched=False
        for sup in suppressions_all:
            if suppression_matches(sup,e):
                sup.matched=True; matched=True
        if not matched:
            filtered.append(e)
    all_errors=filtered
    # Unmatched suppressions
    unmatched=[]
    if settings.is_enabled('information'):
        for sup in list(settings.suppressions):
            if not sup.matched and '*' not in sup.id:
                e=Error('unmatchedSuppression','information',f"Unmatched suppression: {sup.id}",[]); e.rank=rank_for('unmatchedSuppression'); unmatched.append(e)
        if settings.inline_suppr:
            for sup in analyzer.inline_suppressions:
                if not sup.matched and '*' not in sup.id:
                    loc=Loc(sup.file,sup.line or 0,0,'')
                    e=Error('unmatchedSuppression','information',f"Unmatched suppression: {sup.id}",[loc]); e.rank=rank_for('unmatchedSuppression'); unmatched.append(e)
    if unmatched:
        # Filter unmatched by suppressions for unmatchedSuppression id
        tmp=[]
        for e in unmatched:
            matched=False
            for sup in suppressions_all:
                if suppression_matches(sup,e): sup.matched=True; matched=True
            if not matched: tmp.append(e)
        unmatched=tmp
        all_errors.extend(unmatched)
    # Checkers report error
    any_cpp=any(p['language']=='c++' for p in entry_plans)
    active=compute_active_checkers(settings,any_cpp,critical=bool(critical_ids_order))
    active_names=[CHECKERS_DATA[i][0] for i,ok in enumerate(active) if ok]
    if settings.is_enabled('information'):
        if critical_ids_order:
            msg="Active checkers: There was critical errors"
        else:
            msg=f"Active checkers: {len(active_names)}/186"
        if not settings.checkers_report:
            msg+=" (use --checkers-report=<filename> to see details)"
        e=Error('checkersReport','information',msg,[]); e.rank=rank_for('checkersReport')
        # suppressible
        matched=False
        for sup in suppressions_all:
            if suppression_matches(sup,e): sup.matched=True; matched=True
        if not matched: all_errors.append(e)
    # Checkers report file
    if settings.checkers_report:
        try:
            content=make_checkers_report(settings,any_cpp,critical_ids_order)
            with open(settings.checkers_report,'w',encoding='latin-1') as fh: fh.write(content)
        except Exception:
            pass
    # Showtime summary
    print_showtime_summary(settings,_time.time()-run_start)
    # Build output text according format
    if hasattr(analyzer,'raw_stderr') and analyzer.raw_stderr:
        output_text=''.join(analyzer.raw_stderr)
    elif settings.output_format=='sarif':
        output_text=formatter.format_sarif(all_errors)
    elif settings.output_format in ('xml','xmlv2'):
        output_text=formatter.format_xml(all_errors,version=2)
    elif settings.output_format=='xmlv3':
        output_text=formatter.format_xml(all_errors,version=3,active_checkers=active_names,critical_ids=critical_ids_order)
    else:
        output_text=formatter.format_text_errors(all_errors)
    if settings.output_file is not None:
        try:
            with open(settings.output_file,'wb') as fh: fh.write(output_text.encode('latin-1'))
        except Exception:
            pass
    else:
        try: sys.stderr.buffer.write(output_text.encode('latin-1'))
        except Exception: sys.stderr.write(output_text)
    # Plist output
    if settings.plist_output:
        try: write_plist_output(settings,formatter,all_errors,entries)
        except Exception: pass
    # Build dir files
    if settings.cppcheck_build_dir:
        try: write_build_dir(settings,formatter,entries,per_file_errors_map,all_tus,active_names,all_errors)
        except Exception:
            if os.environ.get('CPPCHECK_IMPL_DEBUG'): raise
    # Exit code
    def is_exitcode_suppressed(e):
        for sup in settings.exitcode_suppressions:
            if suppression_matches(sup,e): return True
        return False
    countable=[e for e in all_errors if e.id!='checkersReport' and not is_exitcode_suppressed(e)]
    if settings.error_exitcode is not None and countable:
        return settings.error_exitcode
    if settings.safety and critical_ids_order:
        return 1
    return 0

