def resolve_addons(settings):
    resolved=[]
    for addon in settings.addons:
        kind,path_or_err=find_addon(settings,addon)
        if kind is None:
            return None,path_or_err
        if kind=='json':
            try:
                data=open(path_or_err,'rb').read().decode('latin-1')
                j=json.loads(data)
            except Exception as e:
                # picojson style approx
                near=''
                try:
                    txt=open(path_or_err,'rb').read().decode('latin-1').strip()
                    near=txt[1:] if len(txt)>1 else txt
                except: pass
                return None, f"Loading {addon} failed. syntax error at line 1 near: {near}\n"
            if not isinstance(j,dict) or 'script' not in j:
                return None, f"Loading {addon} failed. 'script' is missing.\n"
            if 'args' in j and not isinstance(j['args'],list):
                return None, f"Loading {addon} failed. 'args' must be an array.\n"
            script=j.get('script','')
            args=[str(x) for x in j.get('args',[])]
            python=j.get('python') or settings.addon_python
            # resolve script as addon name
            sk,sp=find_addon(settings,script)
            if sk is None:
                return None,sp
            if sk!='script':
                return None,sp
            resolved.append({'script_cmd':sp,'script_exec':sp,'args':args,'python':python,'name':os.path.basename(script)[:-3] if script.endswith('.py') else script})
        else:
            script_cmd=path_or_err
            resolved.append({'script_cmd':script_cmd,'script_exec':script_cmd,'args':[],'python':settings.addon_python,'name':os.path.basename(addon)[:-3] if addon.endswith('.py') else addon})
    return resolved,None

def main(argv=None):
    if argv is None: argv=sys.argv[1:]
    # Special first token
    special_order=['--help','-h','--version','--errorlist']
    first_special=None
    for a in argv:
        if a in special_order:
            first_special=a; break
    if first_special in ('--help','-h'):
        out_write(HELP_TEXT); return 0
    if first_special=='--version':
        out_write(f"Cppcheck {VERSION}\n"); return 0
    if first_special=='--errorlist':
        out_write(ERRORLIST_TEXT); return 0
    if not argv:
        out_write(HELP_TEXT); return 0
    try:
        settings=parse_cli(argv)
    except CliError as e:
        out_write(e.msg); return 1
    has_input=bool(settings.paths or settings.project_entries)
    if not has_input:
        out_write("cppcheck: error: no C or C++ source files found.\n"); return 1
    entries,any_input,any_ignored=discover_files(settings)
    lib,lib_err=load_libraries(settings)
    if lib_err:
        out_write(lib_err); return 1
    if lib.unknown_messages:
        for m in lib.unknown_messages: out_write(m)
    resolved_addons,addon_err=resolve_addons(settings)
    if addon_err:
        out_write(addon_err); return 1
    if not entries:
        out_write("cppcheck: error: could not find or open any of the paths given.\n")
        if any_ignored:
            out_write("cppcheck: Maybe all paths were ignored?\n")
        return 1
    analyzer=Analyzer(settings,lib)
    analyzer.ctu_errors=[]
    formatter=Formatter(settings,analyzer)
    total_size=sum(os.path.getsize(e.real) if os.path.isfile(e.real) else 0 for e in entries)
    cumulative=0
    all_tus=[]; per_file_errors_map={}  # id(entry) -> list
    all_errors=[]
    critical_ids_order=[]
    def note_critical(errs):
        for e in errs:
            if getattr(e,'critical',False) and e.id not in critical_ids_order:
                critical_ids_order.append(e.id)
    # Precompute configs per entry (for jobs announcement and normal)
    import time as _time
    run_start=_time.time(); file_times=[]
    entry_plans=[]
    for entry in entries:
        analyzer.register_file(entry.display,entry.real)
        language=determine_language(entry.display,settings,entry)
        entry._config_str=''
        if settings.check_config:
            configs=[(_user_config_string(settings,entry),[])]
            discovered=[]; total_configs=1; toomany=False
        else:
            discovered_items,discovered_strs=discover_configs(analyzer,entry,language)
            user_str=_user_config_string(settings,entry)
            total_configs=1+len(discovered_items)
            limit=settings.max_configs
            selected_items=discovered_items[:max(0,limit-1)] if total_configs>limit else discovered_items
            selected_strs=discovered_strs[:len(selected_items)]
            toomany=(total_configs>limit)
            configs=[(user_str,[])]
            for items,s in zip(selected_items,selected_strs): configs.append((s,items))
        entry_plans.append({'entry':entry,'language':language,'configs':configs,'total_configs':total_configs if not settings.check_config else 1,'toomany':toomany if not settings.check_config else False,'discovered_count':len(discovered_items) if not settings.check_config else 0})
    def print_announcement(plan):
        if settings.quiet or settings.E: return
        entry=plan['entry']
        out_write(f"Checking {entry.display} ...\n")
        if settings.verbose:
            # defines
            defines_parts=[]
            for d in list(entry.extra_defines or [])+list(settings.defines):
                defines_parts.append(d if '=' in d else d+'=1')
            undefs=list/entry.extra_undefs or [])+list(settings.undefines) if False else list(entry.extra_undefs or [])+list(settings.undefines)
            incs=[]
            # project entry includes shown all, CLI includes only if directory exists
            for ip in list(entry.extra_includes or []):
