                if os.path.isdir(ip): incs.append(ip)
            inc_str=''.join(f" -I{ip}/" if not ip.endswith('/') else f" -I{ip}" for ip in incs)
            out_write(f"Defines:{';'.join(defines_parts)}\n")
            out_write(f"Undefines:{(' '+'; '.join(undefs)) if undefs else ''}\n")
            out_write(f"Includes:{inc_str}\n")
