    def process_plan(plan):
        entry=plan['entry']; language=plan['language']; file_errors=[]; startt=_time.time()
        # Clang mode
        if settings.clang is not None and not settings.E:
            # Run clang shell command, output raw to a temporary error list handled via a pseudo raw string stored in plan
            lang='c++' if language=='c++' else 'c'
            cmd_core=f"{settings.clang_exe} -fsyntax-only -Xclang -ast-dump -fno-color-diagnostics -x {lang} {entry.display}"
            try:
                import subprocess as _sp
                cp=_sp.run(cmd_core+" 2>&1", shell=True, capture_output=True, text=True, timeout=30)
                output=cp.stdout or ''
                if cp.returncode!=0:
