                    if not hasattr(analyzer,'raw_stderr'): analyzer.raw_stderr=[]
                    analyzer.raw_stderr.append(f"Failed to execute '{cmd_core} 2>&1' - (exitcode: {cp.returncode} / output: {output})\n")
                else:
