                note_critical(pre_errs+tu_errs)
            combined=pre_errs+tu_errs
            combined.sort(key=lambda e:e.rank)  # stable within rank
            file_errors.extend(combined)
            # Addons per config
            if resolved_addons:
                addon_errs=run_addons_for_file(analyzer,entry,language,cfg_str,result.tokens,tu,resolved_addons)
                file_errors.extend(addon_errs); note_critical(addon_errs)
        if settings.dump and not settings.E and per_config_tokens:
