def run_addons_for_file(analyzer,entry,language,cfg_str,tokens,tu,resolved_addons):
    errors=[]; pid=os.getpid()
    for addon in resolved_addons:
        dump_name=f"{entry.display}.{pid}.dump"
        try:
            content=generate_dump(analyzer,entry,language,[(cfg_str,tokens)])
            with open(dump_name,'w',encoding='latin-1') as fh: fh.write(content)
        except Exception:
            pass
        python=addon.get('python') or 'python3'
        script_cmd=addon['script_cmd']; args_str=' '.join(addon.get('args') or [])
        # Display command format observed: python + two spaces if no args? Construct: f"{python} {args} {script}" where args empty leads two spaces? Reference: 'python3  /path/script.py --cli dump' (python, space, empty, space, script)
        cmd_display=f"{python} {args_str} {script_cmd} --cli {dump_name}" if args_str else f"{python}  {script_cmd} --cli {dump_name}"
        try:
            import subprocess as sp
            cp=sp.run([python,addon['script_exec'],'--cli',dump_name]+list(addon.get('args') or []),capture_output=True,text=True,timeout=30)
            output=(cp.stdout or '')+(cp.stderr or '')
            if cp.returncode!=0 and not output.strip():
                loc=Loc(entry.display,0,0,'')
                e=Error('internalError','error',f"Bailing out from analysis: Checking file failed: Failed to execute addon '{addon['name']}' - exitcode is {cp.returncode}",[loc],critical=True); errors.append(e); analyzer.critical_ids.add('internalError')
                addon['_failed']=True
            elif output.strip():
                # If addon output looks like JSON lines with fields, reference may parse into errors. Minimal support: try parse lines as JSON objects with file/linenr/message/errorId
                parsed=_try_parse_addon_output(output,analyzer)
                if parsed is not None:
                    errors.extend(parsed)
                else:
                    loc=Loc(entry.display,0,0,'')
                    msg=f"Bailing out from analysis: Checking file failed: Failed to execute '{cmd_display}'. {output.strip()}"
                    e=Error('internalError','error',msg,[loc],critical=True); errors.append(e); analyzer.critical_ids.add('internalError')
        except Exception as ex:
            pass
        finally:
            try:
                if os.path.exists(dump_name): os.remove(dump_name)
            except: pass
    return errors

def _try_parse_addon_output(output,analyzer):
    # Addons using cppcheck's python addon API print JSON lines? Try detect all lines are json dicts with errorId
    lines=[l for l in output.splitlines() if l.strip()]
    if not lines: return []
    parsed=[]
    for line in lines:
        try:
            j=json.loads(line)
        except Exception:
            return None
        if not isinstance(j,dict) or 'errorId' not in j: return None
        loc=Loc(j.get('file',''), int(j.get('linenr',0) or 0), int(j.get('column',0) or 0),'')
        parsed.append(Error(j.get('errorId'), j.get('severity','warning'), j.get('message',''),[loc]))
    return parsed

def run_addons_whole(analyzer,resolved_addons):
    errors=[]; pid=os.getpid(); ctu_name=f"{pid}.ctu-info"
    for addon in resolved_addons:
        if addon.get('_failed'): continue
        try:
            with open(ctu_name,'w',encoding='latin-1') as fh: fh.write('')
        except: pass
        python=addon.get('python') or 'python3'; script_cmd=addon['script_cmd']; args_str=' '.join(addon.get('args') or [])
        cmd_display=f"{python} {args_str} {script_cmd} --cli {ctu_name}" if args_str else f"{python}  {script_cmd} --cli {ctu_name}"
        try:
            import subprocess as sp
            cp=sp.run([python,addon['script_exec'],'--cli',ctu_name]+list(addon.get('args') or []),capture_output=True,text=True,timeout=30)
            output=(cp.stdout or '')+(cp.stderr or '')
            if cp.returncode!=0 and not output.strip():
                loc=Loc('',0,0,'')
                e=Error('internalError','error',f"Bailing out from analysis: Whole program analysis failed: Failed to execute addon '{addon['name']}' - exitcode is {cp.returncode}",[loc],critical=True); errors.append(e)
            elif output.strip():
                parsed=_try_parse_addon_output(output,analyzer)
                if parsed is not None: errors.extend(parsed)
                else:
                    loc=Loc('',0,0,'')
                    msg=f"Bailing out from analysis: Whole program analysis failed: Failed to execute '{cmd_display}'. {output.strip()}"
