        files_lines.append(f"{aname}:::{entry.display}")
        per_errs=per_file_errors_map.get(id(entry),[])
        # filter suppressed? We don't have filtered per-file map after global filter; approximate use all_errors for this file primary
        file_errs=[e for e in all_errors if e.locations and e.primary.file==entry.display]
        xml=formatter.format_xml(file_errs,version=2)
        # extract errors content
        m=re.search(r'<errors>(.*?)</errors>',xml,re.S); inner=m.group(1).strip('\n') if m else ''
