def print_showtime_file(plan,settings,elapsed):
    if settings.quiet: return
    if settings.showtime=='file-total':
        out_write(f"Check time: {plan['entry'].display}: {elapsed:.3f}s\n")
    elif settings.showtime=='top5_file':
        out_write('\n')
        for line in SHOWTIME_TOP5: out_write(line+'\n')
        out_write(f"Check time: {plan['entry'].display}: {elapsed:.3f}s\n")
    elif settings.showtime=='file':
        out_write('\n')
        for line in SHOWTIME_TOP5: out_write(line+'\n')

