{"command":"cat > /tmp/genmap.py <<'PY'
import ast, subprocess, os, tempfile, xml.etree.ElementTree as ET, json, shutil
src=open('/tmp/compare2.py').read()
tree=ast.parse(src)
codes=[]
for node in tree.body:
    if isinstance(node,ast.Assign) and getattr(node.targets[0],'id','')=='codes':
        for elt in node.value.elts:
            try:
                val=ast.literal_eval(elt)
            except Exception:
                continue
            if len(val)==2: codes.append((val[0],val[1],'test.c'))
            else: codes.append(val)
# add compare1 simple snippets
src1=open('/tmp/compare.py').read(); tree1=ast.parse(src1)
for node in tree1.body:
    if isinstance(node,ast.Assign) and getattr(node.targets[0],'id','')=='SIMPLE':
        for elt in node.value.elts:
            try: val=ast.literal_eval(elt)
            except: continue
            codes.append((val[0],val[1],'test.c'))
print('codes',len(codes))
types=['autosar','cert-c-2016','cert-cpp-2016','misra-c-2012','misra-c-2023','misra-c-2025','misra-cpp-2008','misra-cpp-2023']
mp={}
for name,code,fn in codes:
    lang='cpp' if fn.endswith('.cpp') else 'c'
    for rt in types:
        d=tempfile.mkdtemp(dir='/tmp')
        try:
            open(os.path.join(d,fn),'w').write(code)
            r=subprocess.run(['/workspace/executable','--xml','--enable=all',f'--report-type={rt}',fn],cwd=d,capture_output=True,text=True,timeout=5)
            if not r.stderr.strip().startswith('<?xml'): continue
            root=ET.fromstring(r.stderr)
            for e in root.iter('error'):
                eid=e.get('id'); guid=e.get('guideline'); clas=e.get('classification')
                key=f"{rt}|{lang}|{eid}"
                val=[guid,clas] if guid else None
                if key in mp and mp[key]!=val:
                    print('conflict',key,mp[key],val)
                mp[key]=val
        except Exception as ex:
            print('err',name,rt,ex)
        finally:
            shutil.rmtree(d,ignore_errors=True)
# Keep only mapped entries
mp={k:v for k,v in mp.items() if v}
print('mapped',len(mp))
open('/tmp/reportmap.json','w').write(json.dumps(mp))
PY
timeout 170 python3 /tmp/genmap.py"}

